\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 (f. 6v2, 19) \plain \f1\caps\lang1033\fs26 2.7: \plain \f1\scaps\lang1033\fs26 Avicenna:\plain \f1\scaps\lang1033\fs26  Epistola ad Hasen\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Epistola Aboali Avicenne ad haso\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 regem.\plain \f1\lang1033\fs26 < (line 20, right) \plain \f1\i\lang1033\fs26 Epistola principis\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 aboali cognomento abinseni\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ad bahasen de re tecta. Protractta sunt inter me et hasen de eo\plain \f1\lang1033\fs26  \u8230 \'85 (f. 10v1, 11) \plain \f1\i\lang1033\fs26 et citrinum completur. iiij. rotis. explicit.\plain \f1\lang1033\fs26  \endash  TK col. 603, 1080, 1036, 1577; ZeIV, pp. 572\endash 586; H. E. Stapleton et al., Two Alchemical Treatises Attributed to Avicenna, in: Ambix. The Journal of the Society for the Study of Alchemy and Early Chemistry 10 (1962), pp. 41\endash 82.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

