\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 (f. 77r1, 40) \plain \f1\caps\lang1033\fs26 2.21: \plain \f1\scaps\lang1033\fs26 Anonymous:\plain \f1\scaps\lang1033\fs26  List of alchemical equivalents\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Almizadir. Aleziadyr. Sal\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 armoniacus preparatus.\plain \f1\lang1033\fs26  \u8230 \'85 (f. 77r2, 40) \plain \f1\i\lang1033\fs26 Cauda draconis idest\plain \f1\i\lang1033\fs26\cf17  \plain \f1\i\lang1033\fs26 mercurius sublimatus.\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Vermiculus idest mercurius.\plain \f1\lang1033\fs26  \endash  List of alchemical equivalents, to which there are a few marginal additions in a contemporary hand and in the fifteenth-century Bastarda.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red255\green102\blue0;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 (f. 77r2, 42) \plain \f1\caps\lang1033\fs26 2.22: \plain \f1\scaps\lang1033\fs26 Anonymous:\plain \f1\scaps\lang1033\fs26  Alchemy, titled Methodus transmutandi metalla\plain \f1\lang1033\fs26  by a later hand. \plain \f1\i\lang1033\fs26 Et quoniam plures sunt vie\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et plures modi ad unum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 finem\plain \f1\lang1033\fs26  \u8230 \'85 In the right margin, probably in the hand of Henricus Cornelius Anchiroandri, for whom see provenance section above, is: \plain \f1\i\lang1033\fs26 Methodus\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 transmutandi\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 metalla.\plain \f1\lang1033\fs26  (f. 84r1, 4) \u8230 \'85 \plain \f1\i\lang1033\fs26 currat super laminam et facies eam\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 albam.\plain \f1\lang1033\fs26  \endash  TK col. 523, noted from the Art Ancien description of this codex. The text ends earlier than was noted in the Art Ancien description, copied by TK, with the result that the following text escaped notice.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red255\green102\blue0;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 (f. 84r1, 5) \plain \f1\caps\lang1033\fs26 2.23: \plain \f1\scaps\lang1033\fs26 Richard de Fournival:\plain \f1\scaps\lang1033\fs26  Opus Arturi, or De arte alchemica\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Dixit expositor. Accepi arsenicum et elegi in quo sunt quedam\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 vene quasi auree\plain \f1\lang1033\fs26  \u8230 \'85 There are two slight drawings of apparatus by the scribe, partly in column-space left blank, and partly in the right margins of ff. 84v and 85r. (f. 85v2, 19) \u8230 \'85 \plain \f1\i\lang1033\fs26 Et si .x. partes istius misceas\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 cum duabus optimi\plain \f1\lang1033\fs26  [?] \plain \f1\i\lang1033\fs26 erit sol bonus.\plain \f1\lang1033\fs26  \endash  TK col. 451, 450, DWS no. 174, etc. The endings quoted by DWS from various MSS all differ from one another, and that found in the present codex differs also from those cited by Mrs. Singer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red255\green102\blue0;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 (f. 85v2, 21) \plain \f1\caps\lang1033\fs26 2.24: \plain \f1\scaps\lang1033\fs26 Anonymous:\plain \f1\scaps\lang1033\fs26  Alchemy.\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Incipit quedam alia practica alchymie cuiusdam alterius phylosophu\plain \f1\lang1033\fs26 s\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Et quoniam\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 de oleo tartari in ea\plain \f1\lang1033\fs26  \u8230 \'85 In the upper margin the fifteenth-century Bastarda hand has written: \plain \f1\i\lang1033\fs26 Incipit liber tercius\plain \f1\lang1033\fs26 , and opposite the incipit a later hand, probably that of Henricus Cornelius, has written: \plain \f1\i\lang1033\fs26 LIB. III. \plain \f1\lang1033\fs26 At line 26: \plain \f1\i\lang1033\fs26 Oleum tartarum ad hoc opus sicut\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 fit. Recipe de tartaro quantum vis\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et pone\plain \f1\lang1033\fs26  \u8230 \'85 (f. 86r1, 19) \plain \f1\i\lang1033\fs26 Post hec dicendum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 de oleo alkali\plain \f1\lang1033\fs26  \u8230 \'85 (f. 86r2, 3) \plain \f1\i\lang1033\fs26 Post hec dicendum est de sublimacione\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 et praeparacione et confeccione auripigmenti\plain \f1\lang1033\fs26  \u8230 \'85 (f. 86r2, 12) \plain \f1\i\lang1033\fs26 Nunc de eius sublimacione est dicendum.\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Recipe scoria ferri\plain \f1\lang1033\fs26  \u8230 \'85 (f. 86v1, 18) \plain \f1\i\lang1033\fs26 Post de eius confeccione ulteriori\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 est dicendum\plain \f1\lang1033\fs26  \u8230 \'85 (f. 86v2, 23) \plain \f1\i\lang1033\fs26 Nunc in nomine domini ad opus nostrum procedamus. Recipe laminas veneris\plain \f1\lang1033\fs26  \u8230 \'85 (f. 87r1, 1) \plain \f1\i\lang1033\fs26 Item alius modus. Accipe sicut prius\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 spongias\plain \f1\lang1033\fs26  [?] \plain \f1\i\lang1033\fs26 cum auripigmento\plain \f1\lang1033\fs26  \u8230 \'85 (f. 87r1, 11) \plain \f1\i\lang1033\fs26 Item alius modus. Accipe venerem\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 calcinatam et imbibe cum oleo tartari\plain \f1\lang1033\fs26  \u8230 \'85 (f. 87r1, 22) \plain \f1\i\lang1033\fs26 Item si vis procedere cum levibus\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 denarijs locatis\plain \f1\lang1033\fs26  [?] \u8230 \'85 (f. 87r1, 28) \plain \f1\i\lang1033\fs26 Item alius modus. Accipe auripigmentum\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 sublimatum\plain \f1\lang1033\fs26  \u8230 \'85 \endash  TK col. 523, noted only from the Art Ancien description of this codex.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red255\green102\blue0;}

