\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 f. 400ra\endash rb \plain \f1\scaps\lang1033\fs26 Oratio ad sanctam Birgittam\plain \f1\scaps\lang1033\fs26 .\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Oracio de sancta Birgitta.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O amantissima Christi sponsa summo principi in celestibus valde\plain \f1\lang1033\fs26  [K. S.: \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 perhenniter vivit et regnat deus in celis. Amen.\plain \f1\lang1033\fs26  Prayer: (f. 400rb\endash va) \plain \f1\i\lang1033\fs26 Felix regnicola paradisi, sancta Birgitta, sponsa dei grata, mistica discipula\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 qua valeam cum te vivere perpetue. \plain \f1\lang1033\fs26 Followed by: \plain \f1\i\lang1033\fs26 O Birgitta, pro nobis tuum rogita sponsum ut digni efficiamur promissionibus Christi. Oremus.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Collecta.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Deus qui ecclesiam tuam per beatam Birgittam sacris illuminare dignatus es\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 devotis mentibus exequamur per dominum nostrum Ihesum Christum etc.\plain \f1\lang1033\fs26  \endash  See Undhagen, Sancta Birgitta. Revelaciones. Book I, see above, p.\~179, n.\~7.]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset161 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red153\green0\blue204;}

