\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 20v\endash 21v \plain \f1\scaps\lang1033\fs26 Prayer to Christ.]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Das nachuolgendt gepett solman \plain \f1\lang1033\fs26 [!]\plain \f1\i\lang1033\fs26  sprechen vor einem crucifix vnsers herrenn Ihesu Cristi.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O herr vnd got, ich kom f\u252 \'fcr dich als ain armer pettl\u228 \'e4r \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 f\u252 \'fcr ein reichen herren\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 du aller miltigister vater. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 49v\endash 51v (from Tegernsee).]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 21v\endash 23r \plain \f1\scaps\lang1033\fs26 Prayers of the Passion\plain \f1\scaps\lang1033\fs26 .]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ain gepet von der angst vnsers lieben herren Ihesu Cristi am \u246 \'f6lperg.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O aller liebster herr Ihesu Criste, ich betracht vnd gedenck mitleidenlich von ganczem herczen die grosen angst\plain \f1\lang1033\fs26  \u8230 \'85; (f.\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 22v) >\plain \f1\i\lang1033\fs26 Ain anders gepet von vnsers herren Ihesu Cristi angst am \u246 \'f6lperg.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, warer go\plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 t\plain \f1\lang1033\fs26 < [end\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 hidden by tape] \plain \f1\i\lang1033\fs26 vnd mensch, du pist der aingeporen\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 sun deines himlischen vaters, ich armer s\u252 \'fcn\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26 der\plain \f1\lang1033\fs26 > \plain \f1\i\lang1033\fs26 erman dich deiner grossen vnd herczenlichen traurigkait, angst vnd todtlicher nott \plain \f1\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd darumb die sundt vermeiden, deinen gotlichen willen vnd wolgefallen alzeit volpringhen. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 2961, ff. 69v\endash 71r (from Tegernsee).]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 23v\endash 24v \plain \f1\scaps\lang1033\fs26 Prayer of Confession\plain \f1\scaps\lang1033\fs26 .]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ain andechtigs gepet fur die sundt vnd zu begeren gut tugend wider die sundt.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O almelhtiger \plain \f1\lang1033\fs26 [!]\plain \f1\i\lang1033\fs26  ewiger got, ich vnwirdiger sunder pit vnd beger von dir \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 au\u223 \'df grundt meines herczen vnd gemuets gnad vnd vergebnu\u223 \'df aller meiner sundt\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 dir, almechtiger got, ze lob vnd ze ere vnd meiner seel zu ewigem hail vnd saligkait. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 4640, ff. 251v\endash 255v; Cgm 2961, ff. 68r\endash 69r and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 52r\endash 55r (all from Tegernsee). \endash  Up to this point, the order of prayers in MS 28 corresponds to the one in M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269 (Tegernsee, 1st half of the 16th century), ff. 16r\endash 55r, see Gisela Kornrumpf / Paul-Gerhard V\u246 \'f6lker, Die deutschen mittelalterlichen Handschriften der Universit\u228 \'e4tsbibliothek M\u252 \'fcnchen (Die Handschriften der Universit\u228 \'e4tsbibliothek M\u252 \'fcnchen 1), Wiesbaden 1968, pp. 262\endash 264.]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: f. 24v \plain \f1\scaps\lang1033\fs26 Benediction\plain \f1\lang1033\fs26 .] >\plain \f1\i\lang1033\fs26 Ain gepet von dem heiligen creucz Ihesu Cristi.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Ich pit dich, du heiligs creucz, dar an vnser hail gewurckt ist wordenn, \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 das du mit deiner tugend vnd krafft mein kranckes hercz beschirmest\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 in den weg das \plain \f1\lang1033\fs26 [!]\plain \f1\i\lang1033\fs26  ewigen lebens endest. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 780, f. 178v (from Tegernsee).]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 24v\endash 25r \plain \f1\scaps\lang1033\fs26 Five Invocations to Christ\plain \f1\lang1033\fs26 .\plain \f1\scaps\lang1033\fs26 ]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Die f\u252 \'fcnff gepet Hugonis.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Aller suessister herr Ihesu Criste, durch\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 die wirdigkait deines leichnams, \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 den du an dich hast genomen von der vnvermailigten iunckfrawenn Maria, verleich mir armen sunder, das dein allerheiligster leichnam sey die letzst speis meiner seel\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 deiner wunden pitters leiden. Amen.\plain \f1\lang1033\fs26  \endash  Variant of the so called \ldblquote F\u252 \'fcnf Worte\rdblquote , see Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 55. See M\u252 \'fcnchen, BSB, Cgm 484, ff. 79v\endash 80r and Cgm 5246, ff. 98v\endash 99r (in Dutch) and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 92v\endash 94r (from Tegernsee).]}

