\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: f.\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 35v \plain \f1\scaps\lang1033\fs26 Prayer for \plain \f1\scaps\lang1033\fs26 Communion\plain \f1\lang1033\fs26 .] >\plain \f1\i\lang1033\fs26 Ain gepet, sich tailhafftig zu machen des heiligen sacraments, \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 gots leichnams vnd der heiligen mess.\plain \f1\lang1033\fs26 ]< \plain \f1\i\lang1033\fs26 O herr, almechtiger ewiger got, wir pitten dich durch deinen eingepornen sun\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 vnd eren vnd ewigklichen nyessen. Amen.\plain \f1\lang1033\fs26 ]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 35v\endash 36r \plain \f1\scaps\lang1033\fs26 Prayer against pestilence.\plain \f1\lang1033\fs26 ] >\plain \f1\i\lang1033\fs26 Ain andechtiges gepet wider den g\u228 \'e4chen todt vnd fur die pestilencz\plain \f1\lang1033\fs26 .< \plain \f1\i\lang1033\fs26 Allmechtiger, ewiger, parmhercziger got, ain anfangk vnd endt aller ding\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: (f. 36r) \u8230 \'85 \plain \f1\i\lang1033\fs26 der du das ellendt verloren menschlich geschl\u228 \'e4cht durch die funff wunden deines allerliebsten suns erl\u246 \'f6st hast, ich ellender sunder pit dich durch die tieff der benanten funff wunden \plain \f1\lang1033\fs26 \u8230 \'85\plain \f1\i\lang1033\fs26  du wellest mich erl\u246 \'f6sen vnd behuetten vor dem g\u228 \'e4chen todt \plain \f1\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 vor der ewigen verdampnu\u223 \'df. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 55v\endash 56v (from Tegernsee).]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: f. 36rv \plain \f1\scaps\lang1033\fs26 Benediction\plain \f1\lang1033\fs26 .] >\plain \f1\i\lang1033\fs26 Der segen ist ze sprechen zu morgens vnd gegen der nacht vnd in aller widerwertigkait vnd truebsalen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Dye almechtigkait gottes vaters, die wei\u223 \'dfhait gottes suns, die senfftmuetigkait gottes heiligen geists\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 sein mir ain sig aller meiner feindt\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd in der stundt des tods. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 780, f. 178r (from Tegernsee).]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 36v\endash 42r \plain \f1\scaps\lang1033\fs26 Rosary about the Life of Jesus Christ\plain \f1\lang1033\fs26 , with 5 x 10 clauses.] >\plain \f1\i\lang1033\fs26 In dem namen vnsers lieben herren Ihesu Cristi vahet sich hye an der heilig vnd s\u228 \'e4lig rosenkrancz der lobsamen iunckfrawen Marie \plain \f1\lang1033\fs26 \u8230 \'85 [K. S.: (f. 37r) \u8230 \'85 \plain \f1\i\lang1033\fs26 Der erst zehener ist von weissen rosen. Das ist von der raynen vnd keusch\plain \f1\lang1033\fs26  (f. 37v) \plain \f1\i\lang1033\fs26 enpfachung, gepurdt vnd kindthait Cristi pis auff sein heilig tauff.\plain \f1\lang1033\fs26 ] \u8230 \'85\plain \f1\i\lang1033\fs26  Sprich als hernach geschriben st\u228 \'e4tt.\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26  Gruest seist, Maria genaden vol, der herr mit dir, du bist gesegent\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 Den du, sein allerliebste muter, mit deiner handt arbait fleissigklich gen\u246 \'f6rt vnd mit im ain heiligs leben gefuert hast. Amen.\plain \f1\lang1033\fs26  (f. 38v) >\plain \f1\i\lang1033\fs26 Der ander zehener ist von gruenen rosen. Das ist von der tauff Cristi pis auff das letzst \u246 \'f6sterlich abend essen \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Pater noster etc. Ave Maria. Ihesus Cristus.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Den sand Iohannes im Iordan getaufft\plain \f1\lang1033\fs26  \u8230 \'85 (f. 39r) \u8230 \'85 \plain \f1\i\lang1033\fs26 Der an seinem letzsten abendessen das heilig sacrament \plain \f1\lang1033\fs26 \u8230 \'85\plain \f1\i\lang1033\fs26  \endash  \plain \f1\lang1033\fs26 \u8230 \'85\plain \f1\i\lang1033\fs26  vnd auffgeseczt hat. Amen.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Der drit zehener ist von rottenn rosen. Das ist von dem pitteren leiden vnd vergiessung des rosenfarben\plain \f1\lang1033\fs26  (f. 39v) \plain \f1\i\lang1033\fs26 pluots Ihesu Cristi vor der creuczigung. Pater noster etc. Ave Maria etc.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Der im garten am \u246 \'f6lberg in \u228 \'e4ngsten gepet\plain \f1\lang1033\fs26  \u8230 \'85 (f. 40r) \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd dir, seiner liebsten muter, vnd andern frawen, die in klagten, zu geredt hat. Amen.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Der vierd zehener ist von praunen rosen vnd bedeut die creuczigung, marter vnd sterben Ihesu Cristi\plain \f1\lang1033\fs26  \u8230 \'85 (f. 40v) \plain \f1\i\lang1033\fs26 Pater noster etc. Ave Maria etc. Ihesus.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Der plos vnd nackent mit seinen heiligen henden\plain \f1\lang1033\fs26  \u8230 \'85 (f. 41r) \u8230 \'85 \plain \f1\i\lang1033\fs26 der dir, seiner traurigisten muter, von dem creucz todter in dein scho\u223 \'df gelegt ward, von dir schmerczlich bewaindt vnd beklagt vnd erwirdigklich begraben ist worden. Amen.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Der funfft zehener ist von gulden rosen. Das ist von der glori der vrstendt, vnt\u246 \'f6dlichait vnd auffaret Cristi, auch von der glori Marie, der iunckfrawen. Pater noster etc. Ave Maria etc. Ihesus.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Der die heiligen alu\u228 \'e4ter au\u223 \'df der vorhel erledigt vnd erfreudt hat\plain \f1\lang1033\fs26  \u8230 \'85 (f. 41v) \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd dir, seiner liebsten muter, sey lob vnd preis, guettigkait vnd parmherczig\plain \f1\lang1033\fs26 - (f. 42r) -\plain \f1\i\lang1033\fs26 kait, klarhait vnd freudt in ewiger s\u228 \'e4ligkait on endt. Amen.\plain \f1\lang1033\fs26  \endash  The 50 clauses correspond to those by Jakob Sprenger, with only slight deviations. Ed.: Wolfgang Kliem, Die sp\u228 \'e4tmittelalterliche Frankfurter Rosenkranzbruderschaft als volkst\u252 \'fcmliche Form der Gebetsverbr\u252 \'fcderung, Frankfurt/Main 1963, pp. 134\endash 138. See M\u252 \'fcnchen, BSB, Cgm 840, ff. 358r\endash 368v; Cgm 845, ff. 214r\endash 227v; Cgm 4637, ff. 228v\endash 249r; Cgm 4640, ff. 62r\endash 69v and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 266, ff. 113r\endash 122r; 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 95v\endash 107v (from Tegernsee).]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 42r\endash 44r \plain \f1\scaps\lang1033\fs26 Indulgence, Instruction for the Rosary and\plain \f1\lang1033\fs26  \ldblquote \plain \f1\scaps\lang1033\fs26 Von der\plain \f1\scaps\lang1033\fs26  Rosenkranzbruderschaft\plain \f1\scaps\lang1033\fs26 \ldblquote \plain \f1\scaps\lang1033\fs26 .\plain \f1\lang1033\fs26  Indulgences of Popes Sixtus IV, John XXII, Innocent VIII, and Julius II.] >\plain \f1\i\lang1033\fs26 Hye nachuolgt ain sch\u246 \'f6ne rubrick von dem ablas vnnd nuczperkait des rosenkrancz \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 der lobsamen vnd raynen iunckfrawen Marie \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 das man von dem rosenkrancz vil vnd grossen ablas hat\plain \f1\lang1033\fs26  \u8230 \'85 (f. 43r) \u8230 \'85 \plain \f1\i\lang1033\fs26 Von der bruderschafft des rosenkrancz vnd psalter vnser frawen\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 Sprich nach einem yedlichen gepetlin ain Ave Maria etc.\plain \f1\lang1033\fs26 < Parts of rubric obscured by gray ink. [K. S.: Other mentioned authorities: Bernardinus de Bustis, \plain \f1\i\lang1033\fs26 Franciscus von Prittania\plain \f1\lang1033\fs26 , Alanus de Rupe, and Holy Roman Emperor Frederick III.] (f. 44r) Text: \plain \f1\i\lang1033\fs26 O aller erwirdigiste kunigin der parmherczigkait, ich grue\u223 \'df den erwigen temel\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 mit den aller k\u246 \'f6stp\u228 \'e4rlichesten gaben aller genaden vnd tugendten. \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Ave Maria etc. Ihesus Cristus. Amen.\plain \f1\lang1033\fs26 <]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 44v\endash 47r and 52r\endash 53v (ff. 52r\endash 53v are incorrectly bound and should have been placed after f. 45v) \plain \f1\scaps\lang1033\fs26 Rosary about the Life of Jesus Christ\plain \f1\lang1033\fs26 , with 28 clauses\plain \f1\scaps\lang1033\fs26 .]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Hye nachuolgt ain ander sch\u246 \'f6ner vnd besunder andechtiger rosenkrancz \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Gegruest seist Maria etc. vnd nach yedlichem artikel sprich Amen vnd nit\plain \f1\lang1033\fs26  [sic] \plain \f1\i\lang1033\fs26 nach dem Aue Maria. Ihesus Cristus,\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26  den du hast empfangen von dem heiligen geist in aller raynigkait,\plain \f1\lang1033\fs26  [K. S.:\plain \f1\i\lang1033\fs26  der mach vns fruchtpar durch sein g\u246 \'f6tliche forcht in gutten wercken\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 seines g\u246 \'f6tlichen angesichts nach disem leben in ewigkait. Amen.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 1513.\plain \f1\lang1033\fs26 < \endash  See Falk Eisermann, Abla\u223 \'dfgebete (mit Bezug auf Papst Sixtus IV.), in: Verfasserlexikon, vol. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, col. 4\endash 7.]}

