\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 47r\endash 51v, 54r\endash 59v \plain \f1\scaps\lang1033\fs26 Prayers to the Virgin\plain \f1\lang1033\fs26 .
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 47r\endash 48r) >\plain \f1\i\lang1033\fs26 Ain sch\u246 \'f6nes gepet zu der raynen iunckfrawen Maria fur die pestilencz.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O Maria, du pist das wolgeriert v\u228 \'e4\u223 \'dflein des heiligen geists\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: (f. 47v) \u8230 \'85 >\plain \f1\i\lang1033\fs26 Das gepet oder collecten.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du aller guettigister herr Ihesu Criste, ein sun des lebendigen gots\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 verleich vns armen deinen dienern vnd dienerin durch dein pitters sterben\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 vberwindung des g\u228 \'e4hen vnfursichtigen tods\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 der du pist gesegnet in ewigkait. Amen.\plain \f1\lang1033\fs26 ]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 48r\endash 49r) [K. S.: \plain \f1\scaps\lang1033\fs26 Prayer of the Compassion of the Virgin\plain \f1\scaps\lang1033\fs26 .]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ain gepet von herczenlichen mitleiden vnser lieben frawen, der himelkunigen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O eya, du allerwirdigiste muter des aingepornen sun gots\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 mein seel opfert dir das innigklich vnd herczenlich mitleiden\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 ich dardurch kom zu den ewigenn freuden. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 2961, ff. 72v\endash 73v and Budapest, Sz\u233 \'e9ch\u233 \'e9nyi-Nationalbibliothek, Cod. germ. 16, ff. 49r\endash 50r.]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 49r\endash 50r) >\plain \f1\i\lang1033\fs26 Ain andechtigs gepet von den siben klagen vnd schmerczen der muter gottes Marie, der iunkfrawenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O Maria, ein iunckfraw ob allen iunckfrawen, ein muter Ihesu Cristi,\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 bedenck des schmerczens, den du hast gehabt, da sandt Symeon sprach\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 gedenck mein in allen meinen n\u246 \'f6tten vnd angsten. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 2961, ff. 75r\endash 76r (from Tegernsee).]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilv l0 (ff. 50r\endash 51r) [K. S.: \plain \f1\scaps\lang1033\fs26 Liturgy of the Hours of the Compassion of the Virgin.]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Hye nachuolgen die syben tagzeit vnser lieben frawen Marie etc.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Maria, muter, rayne mayd, zu m\u246 \'f6tten zeit ward dir herczlichs laid\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 verkundt von Ihesu, deinem kindt\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 erledig au\u223 \'df ewiger nott. Amen.\plain \f1\lang1033\fs26 ] Includes sections for Prime through Compline and >\plain \f1\i\lang1033\fs26 zu der Aue Maria zeit\plain \f1\lang1033\fs26 <. \endash  [K. S.: Ed.: Philipp Wackernagel, Das deutsche Kirchenlied von der \u228 \'e4ltesten Zeit bis zu Anfang des XVII. Jahrhunderts, vol. 2, Leipzig 1867, pp. 508 f., no. 663. For work and tradition see Nigel F. Palmer, Tagzeitengedichte, in: Verfasserlexikon, vol. 9, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1995, col. 577\endash 588, here col. 587 (no. 22); Gisela Kornrumpf, Tagzeitengedichte, in: Verfasserlexikon, vol. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, col. 1476\endash 1488, here col. 1479 (no. 22, MS mentioned). See M\u252 \'fcnchen, BSB, Cgm 4640, ff. 59r\endash 61r.]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 51rv and 54rv) >\plain \f1\i\lang1033\fs26 Ain andechtigs gepet von vnser lieben frawen Marie.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O liebe vnd aller liebste Maria,\plain \f1\lang1033\fs26  (f. 51v) \plain \f1\i\lang1033\fs26 edle suesse kunigin, ich vnwirdiger aller creatur naig mich\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 zu deinen genaden\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 das du sy pringst f\u252 \'fcr das fron antlicz deines herczen lieben kinds. Amen.\plain \f1\lang1033\fs26  \endash  Ed.: Klapper, Schriften Johanns von Neumarkt, see above, p. 289 f., no. 78. See M\u252 \'fcnchen, BSB, Cgm 780, ff. 170r\endash 171r; Cgm 2961, ff. 73v\endash 75r (both from Tegernsee).]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 54v\endash 56r) >\plain \f1\i\lang1033\fs26 Ain andechtigs vnd guts gepett zu vnser lieben frawen vmb ein s\u228 \'e4ligs end dises muss\u228 \'e4ligen lebens.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du lobsamiste vnd raynnigste iunckfraw vnd muter gotts Maria, o du reicher schacz der g\u246 \'f6tlichen ge\plain \f1\lang1033\fs26 - (f. 55r) -\plain \f1\i\lang1033\fs26 naden \plain \f1\lang1033\fs26 \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich vnwirdiger vnnd muesaliger mensch, betracht mein letzste hynfart\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 fuer sy in die schar aller heiligen, got zu lob vnd er. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 2961, ff. 71v\endash 72v (from Tegernsee).]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 56r\endash 57r) [K. S.: \plain \f1\scaps\lang1033\fs26 Johannes von Indersdorf: Prayer from the cycle for Duke Wilhelm III. \plain \f1\scaps\lang1033\fs26 von Bayern (I, 12).]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ain sch\u246 \'f6nes gepet zu vnser lieben frawen. Das soltn mensche mit aufferhebtem herczen sprechen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O werde iunckfraw Maria, o du himelische kunigin, du zier der engel, erparm dich \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 vber mich armenn menschen\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 das ewig leben, das verleich vns got, der vater, vnd der sun vnd der heilig geist. Amen. 1513.\plain \f1\lang1033\fs26  \endash  See Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 156, n. 971. See also M\u252 \'fcnchen, BSB, Cgm 2961, ff. 79r\endash 80r (from Tegernsee); Cgm 4688, ff. 37r\endash 39v and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 115v\endash 119r (from Tegernsee).]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (f. 57v) [K. S.: \plain \f1\scaps\lang1033\fs26 Golden Ave Maria.]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Das gepet hye nach uolgent ist genant das guldin Aue Maria etc.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Pys gruesset Maria, ein dieren der heiligen driu\u228 \'e4ltigkait \plain \f1\lang1033\fs26 \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 du pist vns versprochen worden von den propheten\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 mein seel behuet vor allem \u252 \'fcbel. Amen.\plain \f1\lang1033\fs26  \endash  See Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 84, n. 492; Burghart Wachinger, \u8218 \'82Goldenes Ave Maria\rquote , in: Verfasserlexikon, vol. 3, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1981, col. 80\endash 84, here col. 80 f., and vol. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, col. 544. See M\u252 \'fcnchen, BSB, Cgm 2961, f. 80v; Cgm 4285, ff. 172v\endash 173r and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 119r\endash 120r (all from Tegernsee).]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (ff. 58r\endash 59r) [K. S.: Maria compared to gems.] >\plain \f1\i\lang1033\fs26 Ain l\u246 \'f6blichs gebet zu vnser liebenn frawen, in dem sy gleicht wirt edlem gestain.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Maria, du gewaltige kunigin der himel, du heilige kaiserin der engel\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 zu dir fliehen die armen, die nit trost haben\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 lauterkait an leib vnd seel. Amen.\plain \f1\lang1033\fs26  \endash  See M\u252 \'fcnchen, BSB, Cgm 4285, ff. 173r\endash 174r (from Tegernsee) and Cgm 4640, ff. 82r\endash 84v, 108r\endash 111r], cf. San Marino, Huntington Library HM 195, art. 11.
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (f. 59rv) [K. S.: \plain \f1\scaps\lang1033\fs26 Prayer to the Virgin\plain \f1\lang1033\fs26 , attributed to Pope Sixtus IV. The rubric is obscured by gray ink:]\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Pabst Sixtus der vierd des namens hat geben von dem nachgeschriben gepet xi tausent iar antlas, als offt man es spricht.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Pis gegruest allerheiligiste Maria, muter gots, kunigin der himel, porten des paradei\u223 \'df\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pit f\u252 \'fcr mein s\u252 \'fcndt. Amen.\plain \f1\lang1033\fs26  \endash  See Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 57; Burghart Wachinger, \u8218 \'82Goldenes Ave Maria\rquote , in: Verfasserlexikon, vol. 3, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1981, col. 80\endash 84, here col. 81 f. (3), and vol. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, col. 544; Falk Eisermann, Abla\u223 \'dfgebete (mit Bezug auf Papst Sixtus IV.), in: Verfasserlexikon, vol. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, col. 4\endash 7. See M\u252 \'fcnchen, BSB, Cgm 4593, f. 186rv; Cgm 4638, ff. 90v\endash 91v and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 48, f. 175v; 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 84v\endash 85v (from Tegernsee).]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls9\ilvl0 (f. 59v) >\plain \f1\i\lang1033\fs26 Von dem nachuolgenden gepet hat man funff iar antlas.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O Maria, ain laitter der himel, ain Saul der welt\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 chom mir zehilff in allen meinen n\u246 \'f6tten\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 o suesse iunckfraw Maria. Amen.\plain \f1\lang1033\fs26  \endash  Similar to M\u252 \'fcnchen, BSB, Cgm 744, f. 6r, 44r.]}

