\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 72v\endash 73v\plain \f1\scaps\lang1033\fs26  Three Prayers to the Virgin.\plain \f1\lang1033\fs26 ]
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls1\ilvl0 (ff. 72v\endash 73r) [K. S.: \plain \f1\scaps\lang1033\fs26 Prayer to the Virgin with indulgence\plain \f1\lang1033\fs26 , attributed to Pope Julius II.] >\plain \f1\i\lang1033\fs26 Bapst Julius der ander gibt achczig tausent iar ablas\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 sprich nach ainem yedlichen petlin Ave Maria.\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26  O aller erwirdigiste kunigin der parmherczigkait, ich grues dein iunckfreulichs hercz\plain \f1\lang1033\fs26  \u8230 \'85; [K. S.: (f. 72v) \plain \f1\i\lang1033\fs26 O aller erwirdigiste kunigin der \plain \f1\lang1033\fs26 (f. 73r) \plain \f1\i\lang1033\fs26 parmherczigkait, ich grues den erwirdigen tempel deines leibs\plain \f1\lang1033\fs26  \u8230 \'85; (73r) \plain \f1\i\lang1033\fs26 O aller erwirdigiste kunigin der parmherczikait, ich grues dein aller edleste seel\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 aller tugend vnd genaden.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ave Maria etc. Ihesus Christus.\plain \f1\lang1033\fs26 < \endash  See M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 120v\endash 121v (from Tegernsee); 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 227, f. 50rv, and Gotha, Forschungsbibliothek, Chart. B 940, ff. 200r\endash 201r.]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls1\ilvl0 (f. 73r) >\plain \f1\i\lang1033\fs26 Zu der muter gots ain guts petlin.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O muter gots, du engel zier, mit ganczer krafft schrey ich zu dir\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 streitt der pitter todt. Amen.\plain \f1\lang1033\fs26 ]
