\uc1
\pard\fi0\li0\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: f. 76v \plain \f1\scaps\lang1033\fs26 Indulgence by Pope Silvester.]\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ain sch\u246 \'f6ne rubrick von der Veronica.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Item. Der heilig vater vnd pabst Siluester verleicht allen den, die yr sund warlich\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 berewt\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd sprech ain Pater noster vnd Ave Maria vor der Veronica pildnu\u223 \'df xxx tausent iar antlas\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 das verleich vns got allen.\plain \f1\lang1033\fs26 ]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 77r\endash 84r \plain \f1\scaps\lang1033\fs26 [Ps.-]\plain \f1\scaps\lang1033\fs26 Birgitta Suecica\plain \f1\scaps\lang1033\fs26 : \plain \f1\scaps\lang1033\fs26 Fifteen prayers\plain \f1\lang1033\fs26 . (ff. 77r\endash 78r) Rubric: >\plain \f1\i\lang1033\fs26 Die nach geschriben funfzehen gepet seind der heiligen frawen sand Brigitten,\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 landsfurstin zu Swedenn, die sy t\u228 \'e4glich vor ainem geschniczten crucifix andechtigklich gepet hat \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 wer die gepet andechtigklich spricht alle tag ain gancz iar, so werden au\u223 \'df seinem geschlecht erl\u246 \'f6st xv seelen au\u223 \'df dem fegfeur\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 Zum achten, wer dise gepet ander mensch lernet, der wirt darumb ain besunderen lon von got enpfahen. Den verleich vns got allen.\plain \f1\lang1033\fs26 < (ff. 78r\endash 84r) Prayers:] \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ewige suessikait,\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 ein wuettung vnd iubilier der, die dich liebhaben, \u252 \'fcbertreffend all freud\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 bedenck aller vor betrachtung vnd inneristen iamers, die du gelitten hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 79r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ware freyhait der engel vnd paradeys der wollusten, bedenck der schreckn\u252 \'fcss vnd grausamkait, die du leidest\plain \f1\lang1033\fs26  \u8230 \'85; (f. 79v) \plain \f1\i\lang1033\fs26 O herr Ihesu Cristi, sch\u246 \'f6pfer der welt\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 bedenck des pitteristenn schmerczens, den du leidest\plain \f1\lang1033\fs26  \u8230 \'85; (f. 79v) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, himlischer arczt, bedenck der kranckhait, schmerczen vnd wunden, die du an dem hohen galgen des creuczs gelitten hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 80r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein spiegel ewiger klarhait, bedenck des trawrens, das du hettest, da du in dem spiegel\plain \f1\lang1033\fs26  \u8230 \'85; (f. 80v) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein kunig vnd ein lieblicher vnnd gancz begierlicher freundt, bedenck des trawerens, das du hettest, da du nackend\plain \f1\lang1033\fs26  \u8230 \'85; (f. 81r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein prunn vnau\u223 \'dfsch\u246 \'f6pflicher guttigkait\plain \f1\lang1033\fs26  \u8230 \'85\plain \f1\i\lang1033\fs26  pit ich dich, lieber herr Ihesu Criste, enzundt vnser begierlichait zu allen volkommen wercken\plain \f1\lang1033\fs26  \u8230 \'85; (f. 81r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein suessigkait der herczen vnd ein vbermessige senftigkait der gemuet\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 verleich vns, pit ich dich, lieber herr, dein heiligen fronleichnam vnd plut zu allen zeitten wirdigklich zu enpfahenn \plain \f1\lang1033\fs26 \u8230 \'85; (f. 81v) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein kunigk, tugent vnd geistliche freudt, bedenck der \u228 \'e4ngsten, die du gelitten hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 81v) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, der anfang vnd das endt vnd ein aynig vnd tugent in allem mittel, bedenck, das du dich von vnser wegen von oben deines haubts pis an die solen in das wasser des leidens gesenckt hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 82r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein abgrundt der tieffisten parmherczigkait, ich pit dich durch die tieff deiner wunden\plain \f1\lang1033\fs26  \u8230 \'85; (f. 82r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein spiegel der warhait, ein zaichen der ainigkait vnd ein pandt der lieb, bedenck der menig deiner wunden\plain \f1\lang1033\fs26  \u8230 \'85; (f. 82v) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, du allerstetister leob vnd ein vntodtlicher vnd vnuberwintlicher kunig, bedenck des schmerczens, den du gelitten hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 83r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein ayngeporner sun des obristen vaters, ein schein vnd figur seines g\u246 \'f6tlichen wesens, bedenck der ynnigen beuelhung, als du dem vater deinen gaist beualhest\plain \f1\lang1033\fs26  \u8230 \'85; (f. 83r) \plain \f1\i\lang1033\fs26 O herr Ihesu Criste, ein warer vnd fruchtp\u228 \'e4rer weinstock, bedenck der \u252 \'fcberfl\u252 \'fcssigen\plain \f1\lang1033\fs26  (f. 83v) \plain \f1\i\lang1033\fs26 vergiessung deines pluets\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 mit allen deinen engeln vnnd heiligenn on end ewigklichen. Amen.\plain \f1\lang1033\fs26  \endash  Ed. of the Latin text: Claes Gejrot, The Fifteen Oes, Latin and Vernacular Versions. With an Edition of the Latin Text, in: Bridget Morris, Veronica O\rquote Mara, The Translation of the Works of St Birgitta of Sweden into the Medieval European Vernacular (The Medieval Translator 7), Turnhout 2000, p. 213\endash 238, here p. 223\endash 229. See Montag, Birgitta von Schweden, see above, p. 25 f.; Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 74 f., n. 413; p. 82 and p. 92; Jan Deschamps / Herman Mulder, Inventaris van de Middelnederlandse handschriften van de Koninklijke Bibliotheek van Belgi\u235 \'eb (voorlopige uitgave), Brussel 2013, p. 100, G78A. See M\u252 \'fcnchen, BSB, Cgm 4483, ff. 66v\endash 85v; Cgm 4597, ff. 114r\endash 124r; Cgm 4638, ff. 259r\endash 290v; Cgm 4640, ff. 210r\endash 223r; Cgm 4698, ff. 222r\endash 231r.] ff. 84v\endash 85v blank.}

