\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 93v\endash 98r \plain \f1\scaps\lang1033\fs26 Prayers to be said after receiving Communion\plain \f1\lang1033\fs26 .
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls7\ilvl0 (ff. 93v\endash 96r) >\plain \f1\i\lang1033\fs26 Hye nachuolgen etliche sch\u246 \'f6ne gepet nach der enpfahung des hochwirdigen sacraments gotzs leichnams,\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 die soll ain mensch mit andacht sprechen, so er enpfangen hat gots leichnam.\plain \f1\lang1033\fs26 ]< \plain \f1\i\lang1033\fs26 Herczenliche danckparkeit, ewigs lob, ere vnd alle s\u228 \'e4ligkait\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 sey dir gesprochen, o himlischer vater\plain \f1\lang1033\fs26  \u8230 \'85 See M\u252 \'fcnchen, BSB, Cgm 4638, ff. 208v\endash 209v; M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 273, ff. 85v\endash 87r and Augsburg, UB, I. 3. 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  10, ff. 95v\endash 96v]; (f. 94r) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du ware speis der engel, o du wares himelprot der ellenden menschen\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 wie hastu dich genaigt zu mir\plain \f1\lang1033\fs26  \u8230 \'85 Ed.: Klapper, Schriften Johanns von Neumarkt, see above, p. 248, no. 60, 8, ll. 3\endash 10. See M\u252 \'fcnchen, BSB, Cgm 4638, f. 210rv and Augsburg, UB, I. 3. 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  10, ff. 96v\endash 97r]; (f. 94r) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams.\plain \f1\lang1033\fs26 < (f. 94v) \plain \f1\i\lang1033\fs26 Herr Ihesu Criste, ich glaub, das ich dich, waren got vnd menschen, enpfangen hab\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: See M\u252 \'fcnchen, BSB, Cgm 4595, f. 185v; Cgm 4638, ff. 210v\endash 212v; Cgm 4639, f. 123v]; (f. 95v) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Ich danck dir, milter vater, gen\u228 \'e4diger herr vnd parmhercziger got\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: See M\u252 \'fcnchen, BSB, Cgm 4595, ff. 185v\endash 186r; Cgm 4639, ff. 125v\endash 126v]; (f. 95v) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams zu der muter gots. Das gepet.\plain \f1\lang1033\fs26 < (f. 96r) \plain \f1\i\lang1033\fs26 O du erwirdige kaiserin, du heligen gepererin gots, heilige Maria, die du den sun des himlischen vaters geporen hast\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 erwirb mir von deinem lieben sun\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 zu der ewigen saligkait. Amen.\plain \f1\lang1033\fs26  See M\u252 \'fcnchen, BSB, Cgm 4639, ff. 126v\endash 127r. \endash  See Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 49, n. 247; p. 53, n. 267; p. 143, n. 897. Textual tradition often according to this or slightly differing compilation, see M\u252 \'fcnchen, BSB, Cgm 484, ff. 81r\endash 83r; Cgm 4595, ff. 185r\endash 186r; Cgm 4639, ff. 122r\endash 127r; M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 273, ff. 99r\endash 104r and Augsburg, UB, III. 1. 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  6, ff. 159v\endash 165r.]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\it ap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4500\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls7\ilvl0 (ff. 96r\endash 98r) [K. S.: \plain \f1\scaps\lang1033\fs26 From the \plain \f1\scaps\lang1033\fs26 \ldblquote \plain \f1\scaps\lang1033\fs26 Ebran-Gebetbuch\plain \f1\scaps\lang1033\fs26 \rdblquote \plain \f1\scaps\lang1033\fs26  of Johannes von Indersdorf: Prayers for Communion (7\plain \f1\scaps\lang1033\fs26 \endash \plain \f1\scaps\lang1033\fs26 10).\plain \f1\lang1033\fs26 ] (f. 96r) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams zu got, dem vater.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O himlischer vater, ewiger got, wer pin ich oder wer hat mir dein genad erworben\plain \f1\lang1033\fs26  \u8230 \'85; (f.\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 96v) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du suess himelprot, herr Ihesu Criste, ain sun gottes, himlischen vaters, in der ewigkait geporen\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich lob dich mit ganczem herczen\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 97r) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Mein seel lobt auch got, den heiligen geist, durch des wurckung der heilig fronleichnam\plain \f1\lang1033\fs26  \u8230 \'85 cf. San Marino, Huntington Library HM\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 195, art. 12; (f. 97v) >\plain \f1\i\lang1033\fs26 Ain anders gepet nach der enpfahung gots leichnams.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O heiliger got, o starcker got, o vnt\u246 \'f6dlicher got, o du heilige driualtigkait\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich pet dich an\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 mit flei\u223 \'df hye auff erd. Amen.\plain \f1\lang1033\fs26  \endash  See Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, see above, p. 153, n. 946; Haage, Traktat, see above, p. 530. See M\u252 \'fcnchen, BSB, Cgm 29, f. 33rv; Cgm 255, f. 39rv; Cgm 841, ff. 128r\endash 133v; Cgm 4285, ff. 182v\endash 185v (from Tegernsee); Cgm 4639, ff. 138r\endash 139v; Cgm 4659, ff. 207v\endash 212r.]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 98v\endash 103v \plain \f1\scaps\lang1033\fs26 Prayers to saints\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Ein gepet in der gemain. Das mag einer petten zu ainem yedlichen zwelfpotten Ihesu Cristi. Das gepet.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du genaden reicher vnd heiliger herr sand N., ein iunger Ihesu Cristi vnd besunder\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 zwelfpot der cristenhait\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 ich pit dich mit inprunstiger begier\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 99r) >\plain \f1\i\lang1033\fs26 Ain gemains gepet. Das mag ain mensch sprechenn zu ainem yedlichen ewangelisten.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du heiliger vnd wirdiger sand N., ain warer ewangelist der g\u246 \'f6tlichen warhait\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 bedenck der genaden vnd s\u228 \'e4ligkait\plain \f1\lang1033\fs26  \u8230 \'85];\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (f. 99r) >\plain \f1\i\lang1033\fs26 Ain gemaines gepet. Das mag ain mensch sprechen zu ainem yelichenn heiligenn, der ain martrer ist gewesenn.\plain \f1\lang1033\fs26 < (f. 99v) \plain \f1\i\lang1033\fs26 O du hochwirdiger vnd strenger ritter gots, heiliger sandt N., du starcker vnd gro\u223 \'dfmechtiger martrer\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 nun pit ich dich in rechter andacht\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 100r) >\plain \f1\i\lang1033\fs26 Ain gepet in der gemain zu vill martrer als sandt Achaci vnd der gleichen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr vn\u252 \'fcberwindtlichenn, lobsamen vnd heiligen martrer sandt N. vnd N., wann yr vmb lieb vnd ere vnsers herren Ihesu Cristi\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pitt ich armer sunder ewer suessigkait\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 100v) >\plain \f1\i\lang1033\fs26 Ain gemains gepet zu ainem peichtiger, der ein pischoff ist gewesen etc.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du hochwirdiger vater sand N., ain schein vnd zier der newen stat Iherusalem \plain \f1\lang1033\fs26 \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich schrey vnd rueff zu dir mit seuffczendem herczen\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 100v) >\plain \f1\i\lang1033\fs26 Ain gepet in der gemain von vill peichtigeren.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr durchleuchtigistenn\plain \f1\lang1033\fs26  (f. 101r) \plain \f1\i\lang1033\fs26 peichtiger Ihesu Cristi, von got wirdig vnd au\u223 \'dferwelt \plain \f1\lang1033\fs26 \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich pit euch mit andacht \plain \f1\lang1033\fs26 \u8230 \'85]; (f. 101r)\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Ain gepet in der gemain zu einem peichtiger, der nit pischoff ist gewesen als sant Benedict, sandt Leonhart, Egidius vnd der gleichenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du s\u228 \'e4liger vnd lieber peichtiger Ihesu Cristi, heiliger sand N., ich vnwirdiger sunder pit dich\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 in aller krafft meiner seel \plain \f1\lang1033\fs26 \u8230 \'85]; (f. 101v) >\plain \f1\i\lang1033\fs26 Ain gepet in der gemain. Das mag ain mensch sprechen zu ainer yedlichen junckfrawenn, die ein martrerin ist gewesen als sandt Katherein, Barbara vnd ander.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Gegruest seist du, allerheiligiste \u252 \'fcberwinderin deiner pittrikait vnd leiden, sand N., ich pit dich\plain \f1\lang1033\fs26  \u8230 \'85 \endash  [K. S.: Up to this point very similar to M\u252 \'fcnchen, BSB, Cgm 780, ff. 172r\endash 178r (from Tegernsee).] (f. 102r) >\plain \f1\i\lang1033\fs26 Ain gepet von vil iunckfrawen in der gemain als sand Vrsula vnd der gleichenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr aller s\u228 \'e4ligisten vnd aller raynisten iunckfrawenn in raynigkait des herczens, leibs\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 vnd der werck\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 ich s\u252 \'fcndiger mensch beuilch mein seel\plain \f1\lang1033\fs26  \u8230 \'85]; (f.\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 102r) >\plain \f1\i\lang1033\fs26 Ain gepet in der gemain. Das mag ein mensch sprechen zu ainer\plain \f1\lang1033\fs26  (f. 102v)\plain \f1\i\lang1033\fs26  yedlichen iunckfrawen, die nit ain martrerin ist gewesen als sandt Scolastica vnd der gleichenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du rainiste vnd heiligiste iunckfraw sand N., du gesegnete praut\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 Ihesu Cristi\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 ich pit dich au\u223 \'df innigkait meines herczen\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 103r) >\plain \f1\i\lang1033\fs26 Ain gepet in der gemain von den frawen, die nit junckfrawen oder martrerin sein gewesen als sandt Anna, Elizabeth vnd der gleichen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du wirdige, aller genaden heilige sandt N., red ain guts wortt fur mich vor dem ewigen got\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 in der himlischenn stat Iherusalem, des ewigen vaterlands. Amen.\plain \f1\lang1033\fs26 ]}

