\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 [K. S.: ff. 103v\endash 117v \plain \f1\scaps\lang1033\fs26 Prayers to angels, the twelve apostles and saints.\plain \f1\lang1033\fs26 ]
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls34\ilvl0 (ff. 103v\endash 106r) [K. S.: \plain \f1\scaps\lang1033\fs26 Prayers to angels, \plain \f1\scaps\lang1033\fs26 one\plain \f1\scaps\lang1033\fs26 \rquote \plain \f1\scaps\lang1033\fs26 s own guardian angel,\plain \f1\scaps\lang1033\fs26  one\plain \f1\scaps\lang1033\fs26 \rquote \plain \f1\scaps\lang1033\fs26 s own apostle and all saints\plain \f1\lang1033\fs26 .] >\plain \f1\i\lang1033\fs26 Ain gepet zu deinem heiligen engel.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O heiliger engel gots, dem ich au\u223 \'df g\u246 \'f6tlicher fursichtigkait beuolhen\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 pin, ich erwirdig vnnd pit dich mit andacht\plain \f1\lang1033\fs26  \u8230 \'85 see M\u252 \'fcnchen, BSB, Cgm 2961, f. 85v and M\u252 \'fcnchen, UB, 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  Cod. ms. 269, ff. 122r\endash 172v (both from Tegernsee)]; (f. 104r) >\plain \f1\i\lang1033\fs26 Ain gepet zu deinem aygen zwelfpoten.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du hochwirdiger zwelfpot vnsers herren Ihesu Cristi, heiliger sand N., du hast treulich\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 vnd manlich gestritten\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 ich rueff zu dir von ganczem herczen\plain \f1\lang1033\fs26  \u8230 \'85 see M\u252 \'fcnchen, BSB, Cgm 2961, f. 86v (from Tegernsee)]; (f. 104v) >\plain \f1\i\lang1033\fs26 Ain andechtigs gepet zu allen heiligen gottes.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du wirdige, hochgelobte vnd rainigiste gepererin gottes, heilig junckfraw Maria, vnd du mein allerliebster vnd heiligister engel\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 vnd gemainklich all heiligen gottes, ich armer s\u252 \'fcndiger mensch pit euch mit andechtigem herzcen\plain \f1\lang1033\fs26  \u8230 \'85 see M\u252 \'fcnchen, BSB, Cgm 780, f. 179rv; Cgm 2961, f. 86rv (both from Tegernsee)]; (f. 105r) >\plain \f1\i\lang1033\fs26 Ain anders gepet zu allen heiligen gottes.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr all heiligen, der nam vnd ged\u228 \'e4chtnuss ist geschriben\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 in dem puech des lebens, ich pit euch durch die ewigkait \plain \f1\lang1033\fs26 \u8230 \'85]; (f.\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 105v) >\plain \f1\i\lang1033\fs26 Ain gepet zu allen heligen engelen gottes mit andacht.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr hochwirdigen vnd heiligen himelfursten, heiligen engelen, erwelt diener des almechtigen kunigs\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 der ewigen glori, ich pit euch durch die genad\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd huett sey alzeit \u252 \'fcber mich. Amen.\plain \f1\lang1033\fs26 ]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls34\ilvl0 (ff. 106r\endash 111r) [K. S.: \plain \f1\scaps\lang1033\fs26 Prayers to the twelve apostles.]\plain \f1\lang1033\fs26  (f. 106r) >\plain \f1\i\lang1033\fs26 Hye nachuolge n andechtige gepet, in sunderhait zu ainem yedlichen heiligen zwelffpott vnd am ersten zu dem heiligen sant Andre.\plain \f1\lang1033\fs26 < (f. 106v) \plain \f1\i\lang1033\fs26 O du hochgelobter vnnd hochwirdiger himelfurst vnd heiliger zwelffpot sand Peter, o du gutter getrewer herter\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: (f. 107r) \u8230 \'85 \plain \f1\i\lang1033\fs26 ich pit dich\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 107v) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen zwelffpoten sand Pauls.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Frew dich vnd frolock, du au\u223 \'dferwelts vas der heiligen kirchen, gottes heiliger apostel sand Pauls\plain \f1\lang1033\fs26  \u8230 \'85; (f. 108r) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heyligen sand Johannes ewangelisten.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Iohannes, du himlischer adler, du besunder freundt gottes\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 kum zu mir mit deiner hilff\plain \f1\lang1033\fs26  \u8230 \'85] cf. San Marino, Huntington Library HM\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 195, art. 13; (f. 108v) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen zwelffpoten sand Andre.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du heiliger sand Andre, zwelffpot vnsers herren Ihesu Cristi, durch des lieb du gelitten hast\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich pit dich diemuettigklich\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 108v) >\plain \f1\i\lang1033\fs26 Ain gepet zu sand Iacob, dem zwelffpotten, genant der gro\u223 \'dfer.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O heiliger zwelffpot sant Iacob, den wir glauben nach menschlicher gestalt\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: (f. 109r) \u8230 \'85 \plain \f1\i\lang1033\fs26 mit fleissigem gepet pit ich\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 109r) >\plain \f1\i\lang1033\fs26 Von sand Philip vnd Iacob apostelen ein gepet.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr lieben heiligen apostelen Cristi, sand Philip vnd Iacob, die yr durch \u252 \'fcberwundung der marter\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pittend fur mich got, den herren\plain \f1\lang1033\fs26  \u8230 \'85]; (f.\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 109v) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen sand Thoman apostelen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Heiliger sand Thoman, du apostel vnd sand pott des herren, der du verdient hast\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pit ich dich \plain \f1\lang1033\fs26 \u8230 \'85]; (f. 109v) >\plain \f1\i\lang1033\fs26 Ain gepet von sand Matheo, dem zwelffpoten vnnd ewangelistenn.\plain \f1\lang1033\fs26 < (f. 110r) \plain \f1\i\lang1033\fs26 O du s\u228 \'e4liger apostel vnd ewangelist sand Matheus, durch die vnendtlichen parmherczigkait\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pit f\u252 \'fcr mich\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 110r) >\plain \f1\i\lang1033\fs26 Ain gutt vnd andechtig gepet zu sandt Bartolme, dem zwelffpottenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O heliger sandt Bartolmee, du apostel vnsers herren Ihesu Cristi, der du in dem land India\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: (f. 110v) \u8230 \'85 \plain \f1\i\lang1033\fs26 pit fur mich armen sunder\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 110v) >\plain \f1\i\lang1033\fs26 Ain gepet von sand Symon vnd Iudas, den heiligen zwelffpottenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr lieben himelfurstenn Symon vnd Iudas, apostelen vnsers herren Ihesu Cristi, die yr die ganczen gegent\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pittend fur mich\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 lebendigen vnd die todten vnd welt durch das feur. Amen.\plain \f1\lang1033\fs26 ]
\plain\par \pard\fi-360\li720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 
\par \pard\li720\fi-360\jclisttab\tx720\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs26\lang1033 \'96\tab}\ls34\ilvl0 (ff. 111r\endash 117v) [K. S.: \plain \f1\scaps\lang1033\fs26 Prayers to saints\plain \f1\lang1033\fs26 .] >\plain \f1\i\lang1033\fs26 Ain gepet zu den vierczenhen notthellfferen. Sprichs mit andacht.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O yr vn\u252 \'fcberwintlichen ritter gottes vnd l\u246 \'f6blichen sighafften heiligen sand Sixt, sand Erasm, sand Blasi\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 pit ich au\u223 \'df ganczen herczen\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 111v) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen martrer vnd ritter sand Sebastian.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du wirdiger vnd strenger ritter gottes, heiliger sand Sebastian, du gro\u223 \'dfmechtiger martrer\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 gottes almechtigen, du hast manlich vil manige pein vnd marter gelitten\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 112r) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen martrer vnd kunig sand Quirein, haubtherren zu Tegernsee.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Ich pit dich, heiliger hochwirdiger martrer vnd kunig sand Quirein, der du durch die lieb gots \plain \f1\lang1033\fs26 [K. S.: \plain \f1\i\lang1033\fs26 manige grosse marter vnd pein von dem\plain \f1\lang1033\fs26  (f. 112v) \plain \f1\i\lang1033\fs26 tyran Claudio vnd zum letzsten die enthaubtung deines leibs gelitten hast\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 112v) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen martrer vnd ritter sand J\u246 \'f6rgen.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O strenger ritter vnd heiliger notthelffer sand J\u246 \'f6rg, der du krefftigklich\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich armer sunder rueff zu dir vmb peystandt vnd hilff\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 113r) >\plain \f1\i\lang1033\fs26 Ain gepet zu dem heiligen martrer sand Laurencz.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O s\u228 \'e4liger vnd gro\u223 \'dfmechtiger martrer sand Laurencz, ich armer sunder\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 pit dich, du wellest fur mich pitten\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 113v) >\plain \f1\i\lang1033\fs26 Ain gepet von dem heiligen martrer sand Cristoff.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Heiliger martrer sand Cristoff, ich pit dich durch den heiligen namen Ihesu Cristi \plain \f1\lang1033\fs26 \u8230 \'85; (f. 114r) >\plain \f1\i\lang1033\fs26 Ain andechtigs gepet zu dem heiligen pischoff vnd peichtiger sand Wolfgang.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du s\u228 \'e4liger vnd wirdiger pischoff Ihesu Cristi, heiliger sand Wolffgang, vndter der regel sand Benedicten gehailigt,\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 ich vnwirdiger sunder pit dich in aller krafft meiner seel\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 114v) >\plain \f1\i\lang1033\fs26 Ain gepet zu der heiligen junckfrawen sand Katherina.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Pis gegruesset, s\u228 \'e4lige junckfraw vnd martrerin sand Katherina, ein tochter des vngelaubigen kunigs\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: \plain \f1\i\lang1033\fs26 ich armer sunder rueff zu dir\plain \f1\lang1033\fs26  \u8230 \'85];\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (f. 115r) >\plain \f1\i\lang1033\fs26 Ain gepet zu der heiligen junckfrawen sand Marga\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26 re\plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 th\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26 a\plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du heilige junckfraw vnd martrerin sand Margaretha, durch dein heiligs leben pist du in diser welt\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 erschynen\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 115v) >\plain \f1\i\lang1033\fs26 Ain gepet zu der heyligen frawen sand Anna, der muter vnser liebenn frawenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du wirdige muter der hymlischen kaiserin vnd aller raynisten vnd hochgelobten iunckfrawen Marie\plain \f1\lang1033\fs26  \u8230 \'85 [K. S.: (f. 116r) \u8230 \'85 \plain \f1\i\lang1033\fs26 o, wer mag oder kan dein wirdigs lob au\u223 \'dfsprechen\plain \f1\lang1033\fs26  \u8230 \'85]; (f. 116v) >\plain \f1\i\lang1033\fs26 Ain gepet zu der heiligen sandt Maria Magdalena, ein ware puesserin.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Erfrew dich, du heilige Magdalena, ein hailsame hoffnung vnd durchscheynender spiegel\plain \f1\lang1033\fs26  \u8230 \'85; (f. 117r) >\plain \f1\i\lang1033\fs26 Ain gepet zu der heiligen frawen vnnd kunigin sand Elizabethenn.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 O du edle fraw sand Elizabeth, erlang mir von got,\plain \f1\lang1033\fs26  [K. S.: \plain \f1\i\lang1033\fs26 das er sich \u252 \'fcber mich erparm\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 vnd nach dem\plain \f1\lang1033\fs26  (f. 117v) \plain \f1\i\lang1033\fs26 j\u228 \'e4merlichen leben die ewigen\plain \f1\lang1033\fs26 ] \plain \f1\i\lang1033\fs26 glori vnd freudt. Amen.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Bruder Paulus, vor zeiten genant Melchior Wigg, au\u223 \'df dem rie\u223 \'df geporen vnd das puechlin geschriben zu Tegernsee anno domini 1513.\plain \f1\lang1033\fs26 <
