\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 1r\endash 6v \plain \f1\scaps\lang1033\fs26 Prayers and readings for marriage\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Vom Vertrawen und\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Einsegnen Braut und Breutigam. Andechtigen Lieben Freunde\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 in Christo dem Herrn Gegenwertige\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Der Herr erhebe sein Angesichte \u252 \'fcber euch und gebe euch Frieden. Amen. Bedencket die armen vmb Gottes willen\plain \f1\lang1033\fs26 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 7r\endash 13v \plain \f1\scaps\lang1033\fs26 Prayers and readings for baptism\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Das Tauffbuchlein. Vermanung an die so die Kinder zur Tauff bringen. Lieben Freunde in Christo. Wir h\u246 \'f6ren alle Tage aus Gottes wort erfahrens auch beyde an unserm leben vnd sterben\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 der stercke dich mit seiner gnade zum Ewigen Leben. Amen. Der Friede des Herrn sei mit dir. Antwort. Amen\plain \f1\lang1033\fs26 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 14r\endash 17v \plain \f1\scaps\lang1033\fs26 Prayers and readings for Communion\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Exhortatio vnd vermahnung vom Sacrament des Altars an die Communicanten. Mein allerliebsten. Uns wird stets durch die Predigt das Evangelij\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Christe du Lamb Gottes der du tregst die Sunde der welt Gib uns deinen Frieden. Amen\plain \f1\lang1033\fs26 . Added on f. 17v by a later hand is a prayer for the dying which\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 begins: \plain \f1\i\lang1033\fs26 Ein gebet welches \u252 \'fcber den Krancken vor der Communion von den umbstehenden kan gesprochen werden. Alm\u228 \'e4chtiger Gott, Himlischer Vater, sintemal dieser Krancke dir nicht\plain \f1\lang1033\fs26  \u8230 \'85 In a different hand are\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 words to be said to the assistants when visiting someone sick: \plain \f1\i\lang1033\fs26 Eine Vermahnung an die umbstehende wenn man einen Krancken besucht. Lieben Fre\u252 \'fcnde! Demnach wir befinden, dass unser lieber Bruder\plain \f1\lang1033\fs26  \u8230 \'85 This\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 addition concludes in the lower margin of f. 18r.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 18r\endash 19v \plain \f1\scaps\lang1033\fs26 Prayers related to Baptism\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Oratio loco Introductionis puerperarum\plain \f1\lang1033\fs26 . Above the first heading, in another hand:\plain \f1\i\lang1033\fs26  Hie werde hergesetzet das Formular von der Nohtta\u252 \'fcffe, die hinten fast am Ende stehet\plain \f1\lang1033\fs26 . Text: \plain \f1\i\lang1033\fs26 Quando partus foelix, Vel mediocris fuit atque infans accepto Baptismo tunc adhuc viuit. Lieben Freunde es ist eine Kindelbetterin, die nachgehaltenem\plain \f1\lang1033\fs26  \u8230 \'85; (f. 18v) \plain \f1\i\lang1033\fs26 Quando infans Baptismum accepit, Sed ante expletum puerperij tempus decessit: In posteriori parte omittantur ea quae de infante loquuntur. Dieselbige befihlet sich nun dem frommen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 19r) \plain \f1\i\lang1033\fs26 Quando infans in partu difficili mortuus natus\plain \f1\lang1033\fs26 . 2 words crossed out. \plain \f1\i\lang1033\fs26 Wiewohl er ihr in Kindesn\u246 \'f6ten\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 seinen G\u246 \'f6ttlichen Segen. Amen\plain \f1\lang1033\fs26 . Added on f. 19v by a later hand: \plain \f1\i\lang1033\fs26 Collecta auf den Sontag Palmarum. Oremus. Herr Gott himlischer Vater, wir dancken, loben und preisen dich\plain \f1\lang1033\fs26  \u8230 \'85 Followed by: \plain \f1\i\lang1033\fs26 Collecta auf Ostern. Christus ist umb unser S\u252 \'fcnde will dahingegeben\plain \f1\lang1033\fs26  \u8230 \'85 Prayer: \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater, der du deinen Sohn umb unser S\u252 \'fcnde Willen dahingegeben\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 lieben Sohn unsern Herrn\plain \f1\lang1033\fs26 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 ff. 20r\endash 42v \plain \f1\scaps\lang1033\fs26 Collects for feasts, Sundays, and special occasions\plain \f1\lang1033\fs26 . Most are preceded by a note (Num. 18, Num. 20, etc.) which may be a reference to a hymn. After the heading may come the 2 opening lines of a hymn, written by the same or a later hand; these are followed by a prayer. Given below is the heading, the number of the hymn [?], the opening line of the hymn, and the opening words of the prayer. \plain \f1\i\lang1033\fs26 Collecta\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 vff das Fest Michaelis. Num. 20. Der Herr hat seinen Engeln befohlen \u252 \'fcber dir\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himmlischer Vater, der du deine Engel zum Schutz\plain \f1\lang1033\fs26  \u8230 \'85; (f. 20v) \plain \f1\i\lang1033\fs26 Auff Ostern Collecta. Num. 11. Christus von den Todten erstanden, stirbt hinf\u252 \'fcrt nimmer\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Alm\u228 \'e4chtiger Gott der du durch den Todt deines Sohnes\plain \f1\lang1033\fs26  \u8230 \'85; (f. 21r) \plain \f1\i\lang1033\fs26 Ein Gebet f\u252 \'fcr die Gemeine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 noth\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 22. Herre handel nicht mit uns nach unsern Sunden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Allm\u228 \'e4chtiger Gott, der du der Elenden Schufftzen\plain \f1\lang1033\fs26  [?] \u8230 \'85; (f. 21v) \plain \f1\i\lang1033\fs26 Vor\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 ein Gnediges Gewitter oder Regen zu bitten\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 23. Aller augen warten auff dich Herr\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Allm\u228 \'e4chtiger Gott, der du alles was da ist regierest\plain \f1\lang1033\fs26  \u8230 \'85; (f. 22r) \plain \f1\i\lang1033\fs26 Auff das Fest Trinitatis\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Num. 18. Wir loben Gott den Vater, Sohn, und den heiligen Geist\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott, der du uns gelehret hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 22v) \plain \f1\i\lang1033\fs26 An Christi Himmelfarts\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 tage\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 13. Christus ist auffgefahren in die H\u246 \'f6he\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 O Allm\u228 \'e4chtiger Herre Gott,\plain \f1\lang1033\fs26  [added above: \plain \f1\i\lang1033\fs26 himlischer\plain \f1\lang1033\fs26 ] \plain \f1\i\lang1033\fs26 Vater, wir bitten dich von hertzen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 23r) \plain \f1\i\lang1033\fs26 Collecta auf Pfingsten\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Num. 16. Schaffe in mir Gott eine reines hertze\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott, lieber Vater, der du (an diesem Tage) deiner glaubigen Hertzen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 23v) \plain \f1\i\lang1033\fs26 Collecta beim\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 begrebnis\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 24. Herr handel nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 O Ewiger Gott und Vater, der du nicht bist ein Gott der Todten\plain \f1\lang1033\fs26  \u8230 \'85; (f. 24r) \plain \f1\i\lang1033\fs26 Ein\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 andere Wieder den Schnellen Todt zu Sterbens zeitenn\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 26. Selig sind die Todten die in dem herrn sterben\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger, Barmhertziger Herre Gott Vater wir bitten dich hertzlich du wollest\plain \f1\lang1033\fs26  \u8230 \'85; (f. 24v) \plain \f1\i\lang1033\fs26 Ein\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Andere\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 23. Herr handel nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater, der du nicht Lust hast an der armen S\u252 \'fcnder Todt\plain \f1\lang1033\fs26  \u8230 \'85 Added below in a later hand: \plain \f1\i\lang1033\fs26 Mehr collecten zur Sterbenszeit besiehe unten zum beschlu\u223 \'df aller collecten, nach dem Fest Michaelis, num. 21.\plain \f1\lang1033\fs26 ; (f. 25r) \plain \f1\i\lang1033\fs26 Collecta auff den Aduent\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 1. Bereitet den Weg dem Herren\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Lieber Herre Gott wecke uns auff\plain \f1\lang1033\fs26  \u8230 \'85; added in a later hand at bottom: \plain \f1\i\lang1033\fs26 Hie wirde auch den Collecte auf den Advent hingesetzt, so nach 3. bl\u228 \'e4tten Zu in den Num. 1\endash 6.\plain \f1\lang1033\fs26 ; (f. 25v) \plain \f1\i\lang1033\fs26 Collecta auff\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Wehenachten\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 2. Das Wort ward fleisch\plain \f1\lang1033\fs26  \u8230 \'85 Given at side as an alternate hymn: \plain \f1\i\lang1033\fs26 Ein kind ist uns gebohren\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Hilff lieber Herre Gott dass wir der Newen lieblichen Geb\u252 \'fcrt\plain \f1\lang1033\fs26  \u8230 \'85; (f. 25v) \plain \f1\i\lang1033\fs26 In Die\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Circumcisionis Domini\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 3. O Herr Gott himlischer Vater wir dancken dir f\u252 \'fcr dein V\u228 \'e4terliche Gnaden\plain \f1\lang1033\fs26  \u8230 \'85; (f. 26v) \plain \f1\i\lang1033\fs26 Collecta am tage der\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Tauff Christi. Num. 7. Herre Gott himlischer Vater der du in der Tauff\plain \f1\lang1033\fs26  \u8230 \'85; [f. 27r: a large \plain \f1\i\lang1033\fs26 X\plain \f1\lang1033\fs26  is drawn over the page, and in the upper left-hand corner a later hand wrote: \plain \f1\i\lang1033\fs26 Haec omittatur\plain \f1\lang1033\fs26 .] \plain \f1\i\lang1033\fs26 Pro\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 pluvia. Herr handel nicht mit uns nach unsern Sunden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Allmechtiger Gott, himlischer vater, der du alles was da ist regierst\plain \f1\lang1033\fs26  \u8230 \'85; (f. 27r) \plain \f1\i\lang1033\fs26 Pro serenitate. Herr Allmechtiger Gott, himlischer vater, der du alles was da ist regierst\plain \f1\lang1033\fs26  \u8230 \'85; (f. 27v) \plain \f1\i\lang1033\fs26 Beim begrebnis. Num. 25. Herr handel nicht mit uns nach unsern Sunden \plain \f1\lang1033\fs26 \u8230 \'85 \plain \f1\i\lang1033\fs26 Alm\u228 \'e4chtiger Ewiger Gott, himlischer Vater, der du durch den todt deines lieben Sohns\plain \f1\lang1033\fs26  \u8230 \'85; (f. 27v) \plain \f1\i\lang1033\fs26 Pro\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 pace. Num. 27. Gott gib friede in deinem lande\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater, der du die heiligen\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 gib deinen dienern den fried\plain \f1\lang1033\fs26  \u8230 \'85; (f. 28r) \plain \f1\i\lang1033\fs26 Collecta auf den Aduent. Num. 1.b. Machet die thore weit, und die th\u252 \'fcr in der Welt hoch\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater wir dancken dir von ganzen hertzen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 28v) \plain \f1\i\lang1033\fs26 Collecta auf Weinachten\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Num. 2. Das Wort ward fleish\plain \f1\lang1033\fs26  \u8230 \'85 Given at side as an alternate hymn: \plain \f1\i\lang1033\fs26 Euch ist heute der heiland gebohren\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater, Wir dancken dir deiner grossen gnade und Barmhertzigkeit, dass du deinen Eingebohrnen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 29r) an \plain \f1\i\lang1033\fs26 X\plain \f1\lang1033\fs26  is drawn through this section: \plain \f1\i\lang1033\fs26 Collecta auf das Newe\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Jahr\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  O Herr Gott himlische Vater wir dancken dir f\u252 \'fcr deine Vaterliche gnaden da\u223 \'df du der armen s\u252 \'fcnder \plain \f1\lang1033\fs26 \u8230 \'85; (f. 29r) \plain \f1\i\lang1033\fs26 Eine andere Collecta auf das\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Newe jahr\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Allm\u228 \'e4chtiger Ewiger Gott, von dem alle gute Gaben herkommen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 29v) \plain \f1\i\lang1033\fs26 Collecta auf Trium Regum\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 5. Herr Gott himlischer Vater der du deinen Eingebohrnen Sohn\plain \f1\lang1033\fs26  \u8230 \'85; (f.  30r) \plain \f1\i\lang1033\fs26 Collecta\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 auf Purificationis Mariae\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 6. Herr Gott himlischer Vater der du deinen Sohn uns zum Heylande bereitet hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 30v) \plain \f1\i\lang1033\fs26 Collecta auf\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Verk\u252 \'fcndigung Mariae\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 8. Herr Gott himlischer Vater wir dancken dir vor deine unaussprechliche gnade\plain \f1\lang1033\fs26  \u8230 \'85; (f. 30v) \plain \f1\i\lang1033\fs26 Collecta Dominicae\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 VII Trinitatis. De peccatrice\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  O Jesu du Sohn des lebendigen Gottes der du Vmb der Sunde\plain \f1\lang1033\fs26  \u8230 \'85; (f. 31r) \plain \f1\i\lang1033\fs26 Collecta auf das Leiden Christi zur\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Fastenzeit\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 9. Christus ist umb unser missethat willen verwundet\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Barmhertziger Ewiger Gott der du deines Einigen Sohns nicht verschonet hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 31r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 10. Die straffe lieget auf ihn, auf da\u223 \'df wir friede hetten\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Vater, Ewiger Gott, der du f\u252 \'fcr uns hast deinen Sohn des Cre\u252 \'fctzes pein lassen leiden\plain \f1\lang1033\fs26  \u8230 \'85; (f. 31r) \plain \f1\i\lang1033\fs26 Collecta Dominicae Palmarum\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  O herr Gott himlischer Vater, der du aus Vaterlicher gnaden deines Eingebohrnen Sohns\plain \f1\lang1033\fs26  \u8230 \'85; (f. 31v) \plain \f1\i\lang1033\fs26 Collecta auf Ostern\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 12. Ich wei\u223 \'df da\u223 \'df mein Erl\u246 \'f6ser lebet\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott, himlisher Vater, der du deinen Eingebohrnen Sohn umb unser S\u252 \'fcnde willen hast dahingegeben\plain \f1\lang1033\fs26  \u8230 \'85; (f. 32r) \plain \f1\i\lang1033\fs26 Collecta auf himmelfahrt\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 14. Ich fahre auf zu meinen Vater und zu euren Vater\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger herr Gott, verleihe uns, die wir gle\u252 \'fcben\plain \f1\lang1033\fs26  [?] \u8230 \'85; (f. 32r) \plain \f1\i\lang1033\fs26 Eine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Andere\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 15. Herr Iesu Christe, du Sohn des allerh\u246 \'f6chsten Gottes der du nun forthin\plain \f1\lang1033\fs26  \u8230 \'85; (f. 32v) \plain \f1\i\lang1033\fs26 Collecta auf Pfingsten\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Num. 17. Herr Iesu Christe, du Sohn des Allm\u228 \'e4chtigen Gottes, wir bitten dich, du wollest durch dein Wort\plain \f1\lang1033\fs26  \u8230 \'85; f. 33rv blank; (f. 34r) \plain \f1\i\lang1033\fs26 Dominica iii.\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Epiphaniae\plain \f1\lang1033\fs26 . Rest of f. 34r blank; (f. 34v) \plain \f1\i\lang1033\fs26 Collecta Dominicae post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 circumcisionem. De Fuga Christi\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Allm\u228 \'e4chtiger und Barmhertziger Gott himlischer Vater wir dancken dir hertzlich, da\u223 \'df du deinen lieben Sohn\plain \f1\lang1033\fs26  \u8230 \'85; (f. 34v) \plain \f1\i\lang1033\fs26 Collecta Dominicae ii Epiphaniae\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26  Herr Gott himlisher Vater wir dancken dir, da\u223 \'df du mit deiner gegenward\plain \f1\lang1033\fs26  \u8230 \'85; (f. 35r) \plain \f1\i\lang1033\fs26 Gemeine Collecten\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 4 post Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Herr Gott Vater der du bist ein besch\u252 \'fctzer\plain \f1\lang1033\fs26  \u8230 \'85; (f. 35r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 3 post Epiphaniam\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Herr Gott Vater verleihe uns einen bestendigen glauben\plain \f1\lang1033\fs26  \u8230 \'85; (f. 35v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Quasimodo\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 geniti\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater der du aus V\u228 \'e4terlicher Liebe uns armen S\u252 \'fcndern\plain \f1\lang1033\fs26  \u8230 \'85; (f. 35v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Laetare\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater von dem wir ohn unterla\u223 \'df\plain \f1\lang1033\fs26  \u8230 \'85; (f. 36r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 7 post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Verschone Herr, verschone unser S\u252 \'fcnde\plain \f1\lang1033\fs26  \u8230 \'85; (f. 36r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 4 post Epiphaniam\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott der du durch deinen heiligen Geist\plain \f1\lang1033\fs26  \u8230 \'85; (f. 36r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 5 post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Epiphaniam\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater wir bitten dich du wollest deinen heiligen Geist in unser hertzen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 36v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 3 post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott Vater der du sehen lessest das Liecht\plain \f1\lang1033\fs26  \u8230 \'85; (f. 36v) \plain \f1\i\lang1033\fs26 Eine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 19 post Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater, wir bitten dich, du wollest durch deinen heiligen Geist uns also leiten\plain \f1\lang1033\fs26  \u8230 \'85; (f. 37r) \plain \f1\i\lang1033\fs26 Eine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Jubilate\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott Vater, der du aus V\u228 \'e4terlicher Wollmeinung\plain \f1\lang1033\fs26  \u8230 \'85; (f. 37r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Rogate\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott der du d\u252 \'fcrch deinen Sohn Vergebung\plain \f1\lang1033\fs26  \u8230 \'85; (f. 37v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 17 post Trinitatem\plain \f1\lang1033\fs26 ]\plain \f1\i\lang1033\fs26 . Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater wir bitten dich du wollest durch deinen heiligen Geist uns also Regieren\plain \f1\lang1033\fs26  \u8230 \'85; (f. 37v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Sexagesima\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Wir dancken dir herr Gott himlischer Vater von grund u nsers hertzens\plain \f1\lang1033\fs26  \u8230 \'85; (f. 38r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Oculi\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater der du uns deinen Sohn geschencket\plain \f1\lang1033\fs26  \u8230 \'85; (f. 38r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Inuocavit\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater der du deinen Sohn unsern Herrn Jesum Christum in diese Welt\plain \f1\lang1033\fs26  \u8230 \'85; (f. 38v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 19 post Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Herr Gott Vater, wir bitten dich du wollest unsere S\u252 \'fcnde gn\u228 \'e4diglich\plain \f1\lang1033\fs26  \u8230 \'85; (f. 38v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 21\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 post Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Herr Gott wir bitten dich hertzlich, du wollest unsern glauben\plain \f1\lang1033\fs26  \u8230 \'85; (f. 38v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 18 post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himmlischer Vater Wir bitten dich du wollest deinen heiligen Geist in unsere hertzen geben\plain \f1\lang1033\fs26  \u8230 \'85; (f. 39r) \plain \f1\i\lang1033\fs26 Von der Nothtauffe\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Wen das kindlein in der noth daheime getauft ist\plain \f1\lang1033\fs26  \u8230 \'85; (f. 40r) \plain \f1\i\lang1033\fs26 Eine andere gemeine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Collecta\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Reminiscere\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Herr Gott, der du bist ein trost der traurigen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 40r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 1 post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott ein besch\u252 \'fctzer aller die auf dich hoffen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 40r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Cantate\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater wir bitten dich du wollest uns den Geist der Warheit\plain \f1\lang1033\fs26  \u8230 \'85; (f. 40v) \plain \f1\i\lang1033\fs26 Eine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 11\plain \f1\lang1033\fs26  (post) \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Barmhertziger Ewiger Gott der du deines Eigenen Sohns nicht verschonet hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 40v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 13 \plain \f1\lang1033\fs26 (post)\plain \f1\i\lang1033\fs26  Trinitatem\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Herre Gott gib uns den rechten Warhaftigen glauben\plain \f1\lang1033\fs26  \u8230 \'85; (f. 40v) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 In die para\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Sceves\plain \f1\lang1033\fs26  (sic)]. \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott der du f\u252 \'fcr uns hast deinen Sohn des Creutzes\plain \f1\lang1033\fs26  \u8230 \'85; (f. 41r) \plain \f1\i\lang1033\fs26 Eine Andere\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Gott, himlischer Vater, wir bitten dich, du Wollest dich deines Volcks\plain \f1\lang1033\fs26  \u8230 \'85; (f. 41r) \plain \f1\i\lang1033\fs26 Eine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Andere\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Herr handele nicht mit uns nach unsern S\u252 \'fcnden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Allm\u228 \'e4chtiger Ewiger Herre Gott, der du den Irrenden das Liecht\plain \f1\lang1033\fs26  \u8230 \'85; (f. 41r) \plain \f1\i\lang1033\fs26 Eine Collecta\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 auf die Zehen Geboth\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 6 et 18 Trinitatis\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Lehre mich, herr, da\u223 \'df ich bewahre dein gesetze\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Allm\u228 \'e4chtiger Ewiger Gott, der du das gottlose wesen hassest\plain \f1\lang1033\fs26  [?] \u8230 \'85; (f. 41v) \plain \f1\i\lang1033\fs26 Eine Collecta auf\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 den Christlichen Glauben\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 3 Epiphaniae, Dominica\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Reminiscere, Dominica 21 post Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Dem gle\u252 \'fcbigen wird sein glaube gereihnet zur gereihtigheit\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Allm\u228 \'e4chtiger Gott, von dem alle gute und vollkommene gaben\plain \f1\lang1033\fs26  \u8230 \'85; (f. 41v) \plain \f1\i\lang1033\fs26 Eine Collecta auf das\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Vater Unser\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica Vocem Iucunditatis item. Dominica XI post\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Das verlangen der Elenden H\u246 \'f6restu herr\plain \f1\lang1033\fs26  \u8230 \'85 Given as an alternate hymn: \plain \f1\i\lang1033\fs26 Ehe sie ruffen, wilich antworten\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Gott himlischer Vater du weissest da\u223 \'df wir in so mancher\plain \f1\lang1033\fs26  \u8230 \'85; (f. 42r) \plain \f1\i\lang1033\fs26 Eine\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Collecta auf das heilige Nachtmal\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 In die Viridium\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 So oft ihr von diesen Brodt esset, und von diesen Kelch trincket\plain \f1\lang1033\fs26  \u8230 \'85 Given as an alternate hymn: \plain \f1\i\lang1033\fs26 Welcher unw\u252 \'fcrdig von diesen Brodt isset, oder von dem Kelch des herrn trincket\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Ach du Lieber Herre Gott, der du uns bey diesen\plain \f1\lang1033\fs26  \u8230 \'85; (f. 42r) \plain \f1\i\lang1033\fs26 Eine Collecta auf die Tauffe\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 4\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Adventus\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 Wer da gle\u252 \'fcbet und getauffet wird, der wird selig werden\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 Herr Barmhertziger Gott, der du uns deinen Lieben Sohn Iesum Christum geschencket hast\plain \f1\lang1033\fs26  \u8230 \'85; (f. 42v) \plain \f1\i\lang1033\fs26 Eine Collecta vom j\u252 \'fcngsten\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Tage\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica 2 Adventus, Dominica 25, 26, 27\plain \f1\lang1033\fs26  (post) \plain \f1\i\lang1033\fs26 Trinitatem\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 O herr Iesu Christe, der du zuk\u252 \'fcnftig bist\plain \f1\lang1033\fs26  \u8230 \'85; (f. 42v) \plain \f1\i\lang1033\fs26 Eine Collecta auf das heilige predigampt\plain \f1\lang1033\fs26 . [added: \plain \f1\i\lang1033\fs26 Dominica\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Misericordiae Domini\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 O Barmhertziger Gott der du gelehret hast die hirten\plain \f1\lang1033\fs26  \u8230 \'85 \plain \f1\i\lang1033\fs26 d\u252 \'fcrch Iesum Christum uns ern Herrn\plain \f1\lang1033\fs26 .}

