\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 F\u252 \'fcnf Wz.: Ochsenkopf: =\~WZIS DE4620-PO-77820 (1518, o. O.); Krone: Siebpaar (Kr1 und Kr3): Krone (Kr1): ~\~WZIS DE4620-PO-54440 (1519, Memel), ~\~WZIS DE4620-PO-54435 (1519, Wolfenb\u252 \'fcttel), ~\~WZIS DE4620-PO-54444 (1520, Memel) und Krone (Kr3): =\~WZIS DE7635-PO-54553 (1518, o. O.); Krone (Kr2): =\~WZIS AT3800-PO-53620 (1517, Hagenau), =\~WZIS DE2730-PO-53621 (1517, Friedberg), =\~WZIS DE4620-PO-53622 (1519, Moskau); Krone (Kr4): =\~WZIS AT3800-PO-53619 (1517, Hagenau), =\~WZIS DE4620-PO-53623 (1519, Moskau)   \u183 \'b7   Lagen: VI\plain \f1\super\lang1033\fs24 11\plain \f1\lang1033\fs22  + (V\endash 1)\plain \f1\super\lang1033\fs24 20\plain \f1\lang1033\fs22  + 5 V\plain \f1\super\lang1033\fs24 70\plain \f1\lang1033\fs22  + VI\plain \f1\super\lang1033\fs24 82\plain \f1\lang1033\fs22 ; das erste Blatt der ersten Lage als Schutzblatt, daher ungez\u228 \'e4hlt; zwischen Bl. 14 und 15 ein Blatt herausgeschnitten (kein Textverlust); die letzte Lage (Bl. 71\endash 82) unbeschrieben   \u183 \'b7   teilweise noch erhaltene Lagensignaturen (Zahlen)   \u183 \'b7   moderne Foliierung in Bleistift (\plain \f1\i\lang1033\fs22 1\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 82\plain \f1\lang1033\fs22 )   \u183 \'b7   Schriftraum 11,7\endash 12 x 6,6\endash 7   \u183 \'b7   22\endash 26 Zeilen   \u183 \'b7   Bastarda mit Schlaufen   \u183 \'b7   eine Hand   \u183 \'b7   rubriziert; 2\endash 5-zeilige (ornamental gespaltene) rote oder blaue Lombarden; Rubrikatorvorgaben am unteren Rand (nach Beschnitt der Hs. nur teilweise erhalten geblieben); Wurmfra\u223 \'df an unterer Ecke Bl. 70\endash 82.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

