\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Durchgehend Textverlust auf Recto- und Versoseite am Innenrand; Textverlust Bl. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  wegen \u252 \'fcberklebter Textteile (Einbandverarbeitung)   \u183 \'b7   Schriftraum 25,4\endash 25,5 x ca. 17   \u183 \'b7   zweispaltig   \u183 \'b7   40 Zeilen   \u183 \'b7   Textualis   \u183 \'b7   eine Hand   \u183 \'b7   rubriziert; 2-zeilige rot-blaue Fleuronn\u233 \'e9e-Lombarden.}

