\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 [Ps.-]\plain \f1\scaps\lang1033\fs26 Birgitta Suecica:\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 F\plain \f1\scaps\lang1033\fs26 \u252 \'fc\plain \f1\scaps\lang1033\fs26 nfzehn Gebete zum Leiden \plain \f1\lang1033\fs26 Christi (mit Einleitungsgebet\plain \f1\scaps\lang1033\fs26 )\plain \f1\lang1033\fs26 . (6\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ) Rubrik: \plain \f1\i\lang1033\fs26 Ez ist zu wi\u223 \'dfen, das dy heylig fraw Sant Byrgitta geborn ist au\u223 \'df dem k\u252 \'fcncklichen stammen von Sweden vnd erhaben ist von dem bapst Bonifacius dem newnden\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 der obgeschryben bapst Bonifacius hat eim igelichen menschen geben xxx tag apla\u223 \'df t\u246 \'f6tlicher s\u252 \'fcnd, der dise gepet also spricht.\plain \f1\lang1033\fs26  (6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Text (Einleitungsgebet): >\plain \f1\i\lang1033\fs26 Das ist der anuang der f\u252 \'fcnfczehen gepet.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Aller g\u252 \'fctigster herr Ihesu Criste, geruch mich, deinem aller heiligsten leyden\plain \f1\lang1033\fs26  (7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 lob zu sagen, vnd gib mir kraft\plain \f1\lang1033\fs26  ... >\plain \f1\i\lang1033\fs26 Pater noster.\plain \f1\lang1033\fs26 < (7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Gebet 1: >\plain \f1\i\lang1033\fs26 Das erst gepet.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Herre Ihesu Criste, du ewige s\u252 \'fc\u223 \'dfikeit deiner liebhaber, ein fr\u246 \'f6likeit, dy alle begird vnd frewd \u252 \'fcber trifft \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 parmhertziger libhaber aller s\u252 \'fcnder, dy sich zu dir keren \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 o gedenck dez dem\u252 \'fctigen vor betrachtens vnd dez innerlichen weynens, daz du lidest\plain \f1\lang1033\fs26\cf17  \plain \f1\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26\cf17  \plain \f1\lang1033\fs26 (14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Gebet 15: >\plain \f1\i\lang1033\fs26 Das xv gepet.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Ihesu Criste, du fruchtperer weinstock \plain \f1\lang1033\fs26 (15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 )\plain \f1\i\lang1033\fs26 , gedenck dez aller \u252 \'fcber fl\u252 \'fc\u223 \'dfigsten deinez plut vergy\u223 \'dfens\plain \f1\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 daz ich verdinlich sey, dich zu loben mit deinen heiligen ewicklichen.\plain \f1\lang1033\fs26  (15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Zwei Schlussgebete: >\plain \f1\i\lang1033\fs26 Dy besli\u223 \'dfung.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Solch vermanung vnd di\u223 \'dfe gepet opfer ich dir, aller liebster herr Ihesu Criste\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 dy sel aller glaubigen enpfahen vergebung aller mi\u223 \'dftat vnd g\u246 \'f6tlich parmhertzikeit vnd ewiges leben. Amen.\plain \f1\lang1033\fs26  \endash  Ed. des lat. Textes: Claes Gejrot, The Fifteen Oes, Latin and Vernacular Versions. With an Edition of the Latin Text, in: Bridget Morris, Veronica O\rquote Mara, The Translation of the Works of St Birgitta of Sweden into the Medieval European Vernacular (The Medieval Translator 7), Turnhout 2000, S. 213\endash 238, hier S. 223\endash 229. Vgl. Ulrich Montag, Das Werk der heiligen Birgitta von Schweden in oberdeutscher \u220 \'dcberlieferung (M\u252 \'fcnchener Texte und Untersuchungen zur deutschen Literatur des Mittelalters 18), M\u252 \'fcnchen 1968, S. 25 f.; Ulrich Montag, Birgitta von Schweden, in: Verfasserlexikon, Bd. 1, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1978, Sp. 867\endash 869, hier Sp. 869, und Bd. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, Sp. 258; Franz Xaver Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit im Spiegel der Gebetbuchliteratur S\u252 \'fcddeutschlands (M\u252 \'fcnchener theologische Studien I, 4), M\u252 \'fcnchen 1952, S. 74 mit Anm. 413, S. 82 und S. 92; Jan Deschamps / Herman Mulder, Inventaris van de Middelnederlandse handschriften van de Koninklijke Bibliotheek van Belgi\u235 \'eb (voorlopige uitgave), Brussel 2012, S. 97, G78A.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 Die f\plain \f1\scaps\lang1033\fs26 \u252 \'fc\plain \f1\scaps\lang1033\fs26 nf Leiden Mariae.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Ein sch\u246 \'f6ne offenbarung, waz genade eim menschen wyderfaren von got, der vn\u223 \'df lieben frawen ermant ir f\u252 \'fcnff hertzen leyt.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Man list in einem p\u252 \'fcchlein, daz wirt zu geschryben sant Johannes ewangelisten, also daz er eins mals waz verz\u252 \'fcckt im geyst\plain \f1\lang1033\fs26  ... (17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) ... \plain \f1\i\lang1033\fs26 sy antwurt, daz sie f\u252 \'fcnf gro\u223 \'df smertzen het erliden vnd sprach: Der erst waz, da ich dich oppfert in den tempel\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 daz er von mir vnd ich von ym nymer gescheyd. Amen.\plain \f1\lang1033\fs26  \endash  Text auch \u252 \'fcberliefert in Augsburg, UB, III. 1. 8\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs26  6, 44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  (um 1500, Augsburg, vgl. Deutsche mittelalterliche Handschriften der Universit\u228 \'e4tsbibliothek Augsburg. Die Signaturengruppen Cod. I. 3 und Cod. III. 1, bearbeitet von Karin Schneider [Die Handschriften der Universit\u228 \'e4tsbibliothek Augsburg. II. Reihe. 1], Wiesbaden 1988, S. 399).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  [\plain \f1\scaps\lang1033\fs26 Mechthild von Hackeborn: \plain \f1\scaps\lang1033\fs26 \u8218 \'82\plain \f1\scaps\lang1033\fs26 Liber specialis gratiae\plain \f1\scaps\lang1033\fs26 \lquote \plain \f1\scaps\lang1033\fs26 ] (\plain \f1\scaps\lang1033\fs26 IV, 56\plain \f1\scaps\lang1033\fs26 )\plain \f1\lang1033\fs26 , dt.: \plain \f1\i\lang1033\fs26 Die heilig selig vnd gotliebe, dy man nennt in der legent Drudis fraw cantrix M\plain \f1\lang1033\fs26 [echthild von Hackeborn] (18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 oppfert eins mals got v\plain \f1\i\super\lang1033\fs24 m\plain \f1\i\lang1033\fs26  iiii\plain \f1\i\super\lang1033\fs24 c\plain \f1\i\lang1033\fs26  vnd lx pater noster, dy het der convent gepett in den eren der f\u252 \'fcnf wunden\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 den solt man sprechen nach den f\u252 \'fcnf pater noster.\plain \f1\lang1033\fs26  (18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Folgt Gebet, lat.: \plain \f1\i\lang1033\fs26 Domine Ihesu Criste, fili dei vivi, suscipe hanc orationem in amore\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 que fidelibus tam vivis quam defunctis.\plain \f1\lang1033\fs26  Folgt dasselbe Gebet, dt.: \plain \f1\i\lang1033\fs26 Herre Ihesu Criste, sun dez lebendigen gotes, enpfahe di\u223 \'df gepet in der \u252 \'fcber treffenlichen lieb, in der du alle wunden deinez\plain \f1\lang1033\fs26  (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 aller heyligsten leibes hast enpfangen\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 der lebendigen vnd toten. Amen.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Vnd der herr sprach aber zu ir:\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Alz lang der s\u252 \'fcnder in den s\u252 \'fcnden ligt\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 daz er mit mir tu, waz er will vnd mag.\plain \f1\lang1033\fs26  \endash  Vgl. Mechthild von Hackeborn, Buch der besonderen Gnade, s. o., S. 297 f. Vgl. zum lat. Gebet Haimerl, Mittelalterliche Fr\u246 \'f6mmigkeit, s. o., S. 92 mit Anm. 546.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  [\plain \f1\scaps\lang1033\fs26 Mechthild von Hackeborn: \plain \f1\scaps\lang1033\fs26 \u8218 \'82\plain \f1\scaps\lang1033\fs26 Liber specialis gratiae\plain \f1\scaps\lang1033\fs26 \lquote \plain \f1\scaps\lang1033\fs26 ] (V, 6)\plain \f1\lang1033\fs26 , Anfangsteil, dt.: >\plain \f1\i\lang1033\fs26 Item de eadem.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Eins mals waz ein swester kranck, dy het got all ir tag in heyliger andacht vnd geistlikeit gedienet, da \plain \f1\lang1033\fs26 (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 )\plain \f1\i\lang1033\fs26  sy f\u252 \'fcr die andechticklich pat\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 het sy vor ny geh\u246 \'f6rt.\plain \f1\lang1033\fs26  (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Folgt Gebet: \plain \f1\i\lang1033\fs26 O ir aller heylsam\u223 \'dften wunden meins aller liblichsten liebhabers Ihesu Cristi, seit gegr\u252 \'fc\u223 \'dfet, seit gegr\u252 \'fc\u223 \'dfet, seit gegr\u252 \'fc\u223 \'dfet in der allmechtigkeit dez vaters\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 erl\u246 \'f6\u223 \'dfung volpracht hat. Da nu dy selb swester die heyligen \u246 \'f6lung solt enpfahen\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 daz du sie f\u252 \'fcr mein angesicht vnvermeiligt antwurtest.\plain \f1\lang1033\fs26  \endash  Vgl. Mechthild von Hackeborn, Buch der besonderen Gnade, s. o., S. 313 f.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  Legende der Margareta von Ungarn, Auszug (zu den f\u252 \'fcnf Wunden Christi). >\plain \f1\i\lang1033\fs26 Von dem nutz der wunden Ihesu Cristi.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Item dy heilig edel junckfraw Margaretha, da man in vngern gro\u223 \'df von helt\plain \f1\lang1033\fs26  ... \plain \f1\i\lang1033\fs26 da sy nu in daz closter kam, da waren ir dy rawhen kleyder swer zu tragen\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 vnd man molt sy alz sant Franciscus\plain \f1\lang1033\fs26 . \endash   Zu Werk und \u220 \'dcberlieferung vgl. Werner Williams-Krapp, \u8218 \'82Margareta von Ungarn\lquote , in: VL, Bd. 5, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 1985, Sp.\~1248\endash 1250, und Bd. 11, Berlin \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26 2004, Sp.\~967.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \endash  23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Von den f\u252 \'fcnf Wunden. >\plain \f1\i\lang1033\fs26 Aber von den heyligen v wunden.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Item hy in der zeit flew\u223 \'dfet au\u223 \'df seiner rechten hant sein vngemessene trew\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 pald kumen zu den edeln wunden vmb apla\u223 \'df.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Offenbarungen zur Passion Christi. >\plain \f1\i\lang1033\fs26 Da hernach sten etliche gar ynnige st\u252 \'fcck, dy vnser herr etlichen seinen besundern frewnten hat geoffenwart von seim leyden. Mandatum.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Dy selig Cristina closterfraw prediger ordens ward eins mals enz\u252 \'fccket zu dem mandatum, daz vn\u223 \'df herr saz mit seinen iungern\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 da er an der sewl stund.\plain \f1\lang1033\fs26  \endash  Die Offenbarungen werden folgenden namentlich genannten Personen zugeschrieben: Christine Ebner, Gertrud [von Hackeborn], Katharina von Siena.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \endash  38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Tagzeitengebet zu Leben und Leiden Christi. >\plain \f1\i\lang1033\fs26 Das gepet ist von dem gantzen leben vnd leyden Cristi, vnd man mag ez teylen in syben tag zeit oder in dy gantzen wochen all tag eins, dar nach sten dy begerung. Feria ii\plain \f1\lang1033\fs26  (?).< \plain \f1\i\lang1033\fs26 In dem namen dez hern Ihesu Cristi werden gepogen alle kny hymelisch, irdisch vnd hellisch. Ich anpet,\plain \f1\lang1033\fs26  (30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ich er, ich sprich dir wol, ich lob dich, herr Ihesu Criste, der du ewiklich von dem hertzen dez vaters geborn pist\plain \f1\lang1033\fs26  ... \endash  ... (36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 vnd p\u246 \'f6\u223 \'df wyder zu geben.\plain \f1\lang1033\fs26  >\plain \f1\i\lang1033\fs26 Nu volgen dy gepet vnd begerung auf dy vorgenden st\u252 \'fcck dez leydens Cristi vnd genad zu erwerben.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Dar vmb pit ich dich, herr Ihesu Criste, daz du dein aller heyligstes leben mit alle dem, daz du zu vn\u223 \'dfm heyl hast getan vnd geliden, oppferst got dem vater\plain \f1\lang1033\fs26  ... \endash  ... \plain \f1\i\lang1033\fs26 dich an vnterla\u223 \'df mit allen engeln vnd heyligen zu loben. Amen.}

