\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 52\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  \endash  53\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26  [De sapientia]. (52\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 \endash 53\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) [Ausz\u252 \'fcge aus\plain \f1\scaps\lang1033\fs26  Biblia sacra\plain \f1\lang1033\fs26 , Liber Proverbiorum]. \plain \f1\i\lang1033\fs26 Audiens sapiens sapientior \plain \f1\lang1033\fs26 \u8230 \'85\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 [Prv 1,5] \u8230 \'85 \endash  \u8230 \'85\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs26 mulier timens dominum ipsa laudabitur\plain \f1\lang1033\fs26  [Prv 31,30]\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  (53\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) [Ausz\u252 \'fcge aus\plain \f1\scaps\lang1033\fs26  Biblia sacra\plain \f1\lang1033\fs26 , Liber Ecclesiastes]\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Omnia tempus habent \plain \f1\lang1033\fs26 \u8230 \'85 [Ecl 3,1] \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 qui considerat nubes numquam metet\plain \f1\lang1033\fs26  [Ecl 11,4]\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  (53\plain \f1\super\lang1033\fs24 ra\endash rb\plain \f1\lang1033\fs26 ) [Ausz\u252 \'fcge aus\plain \f1\scaps\lang1033\fs26  Biblia sacra\plain \f1\lang1033\fs26 , Liber Ecclesiasticus]\plain \f1\i\lang1033\fs26 .\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 Noli esse sicut leo\plain \f1\lang1033\fs26  \u8230 \'85 [Sir 4,35] \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs26 vas confractum sapientiam tenebit\plain \f1\lang1033\fs26  [Sir 21,17]\plain \f1\i\lang1033\fs26 .}

