\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 19\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26  \endash  24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  Litanei mit anlassbezogenen Kollekten. >\plain \f1\i\lang1033\fs26 Anthiphona.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Ne reminiscaris, domine, delicta mea vel parentum meorum\plain \f1\lang1033\fs26  \u8230 \'85 CAO Nr. 3861. (19\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 \endash 21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) Allerheiligenlitanei. >\plain \f1\i\lang1033\fs26 Letania per brevis.\plain \f1\lang1033\fs26 < (20\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Kyrieleyson, Christeleyson, Kyrieleyson\plain \f1\lang1033\fs26  \u8230 \'85 Bemerkenswert: \u8230 \'85 \plain \f1\i\lang1033\fs26 Nicolae\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  Hylari\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  Remigi\plain \f1\lang1033\fs26 , \u8230 \'85 \plain \f1\i\lang1033\fs26 Anthoni\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Hylarion\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Benedicte\plain \f1\lang1033\fs26 ; \u8230 \'85 \plain \f1\i\lang1033\fs26 Anastasia\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Blandina\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Scolastica\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Eufemia\plain \f1\lang1033\fs26 , \u8230 \'85 \plain \f1\i\lang1033\fs26 Petronilla\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Maria Magdalene\plain \f1\lang1033\fs26  \u8230 \'85 (21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Collecta.\plain \f1\lang1033\fs26 < CO Nr. 1143. CO Nr. 4587a. >\plain \f1\i\lang1033\fs26 Alia collecta.\plain \f1\lang1033\fs26 < CO Nr. 2541. (22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Contra tempestates.\plain \f1\lang1033\fs26 < CO Nr. 5a. >\plain \f1\i\lang1033\fs26 Pro serenitate.\plain \f1\lang1033\fs26 < CO Nr. 85. >\plain \f1\i\lang1033\fs26 Pro pluvia.\plain \f1\lang1033\fs26 < CO Nr. 1242. >\plain \f1\i\lang1033\fs26 Pro iter agentibus.\plain \f1\lang1033\fs26 < CO Nr. 151. >\plain \f1\i\lang1033\fs26 Pro apostolico.\plain \f1\lang1033\fs26 < CO Nr. 1287. >\plain \f1\i\lang1033\fs26 Pro reconciliacione peccatoris.\plain \f1\lang1033\fs26 < CO Nr. 1767. (22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Pro infirmo collecta.\plain \f1\lang1033\fs26 < CO Nr. 4072. >\plain \f1\i\lang1033\fs26 Pro famulo.\plain \f1\lang1033\fs26 < CO Nr. 3859. >\plain \f1\i\lang1033\fs26 Pro famula.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Rege, quesumus, domine, famulam tuam\plain \f1\lang1033\fs26  \u8230 \'85 Variante zu CO 5023. >\plain \f1\i\lang1033\fs26 Contra malas cogitaciones.\plain \f1\lang1033\fs26 < CO Nr. 3780. >\plain \f1\i\lang1033\fs26 Contra temptaciones carnis.\plain \f1\lang1033\fs26 < CO Nr. 2264b. >\plain \f1\i\lang1033\fs26 Pro inimicis.\plain \f1\lang1033\fs26 < CO Nr. 1293. (23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Pro peticione lacrimarum.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Omnipotens sempiterne deus, qui sicienti populo \plain \f1\lang1033\fs26 \u8230 \'85 CO Nr. 3779. >\plain \f1\i\lang1033\fs26 Pro elemosinariis nostris.\plain \f1\lang1033\fs26 < \plain \f1\i\lang1033\fs26 Omnipotens sempiterne deus, postulaciones nostras benignus exaudi\plain \f1\lang1033\fs26  \u8230 \'85 Variante zu CO Nr. 3710. >\plain \f1\i\lang1033\fs26 Pro omni gradu ecclesie.\plain \f1\lang1033\fs26 < CO Nr. 2488C. (23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Pro rege collecta.\plain \f1\lang1033\fs26 < CO Nr. 4880a. >\plain \f1\i\lang1033\fs26 Pro tribulacione.\plain \f1\lang1033\fs26 < CO Nr. 1503. >\plain \f1\i\lang1033\f